(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["id"] = {"ui":{"skip":"Langsung ke isi","back":"← Kembali ke AI-gile","lang.button":"Bahasa: {name}","lang.dialog":"Pilih bahasa","lang.search":"Cari bahasa","lang.none":"Tidak ada bahasa yang cocok","lang.notYet":"{name} belum diterjemahkan","theme.aria":"Ganti tema: terang, gelap, atau hitam","theme.toLight":"Ganti ke tema terang","theme.toDark":"Ganti ke tema gelap","theme.toBlack":"Ganti ke tema hitam (hitam pekat, nyaman untuk layar OLED)","words.underline":"Garis bawahi kata-kata ini di halaman","words.underlineHelp":"Arahkan kursor atau ketuk kata bergaris titik-titik untuk melihat artinya.","words.col.todo":"Kartu yang dipilih untuk saat ini: tim akan mulai dari sini berikutnya.","words.col.doing":"Sebuah AI sedang mengerjakan kartu ini sekarang.","words.col.review":"Satu AI sudah selesai bekerja; AI lain memeriksanya sebelum sampai ke kamu.","words.col.verify":"Menunggumu: coba dan beri tahu apakah berfungsi.","words.col.team":"Catatan atau jawabanmu, menunggu diambil oleh tim.","words.col.done":"Selesai dan diterima.","index.title":"AI-gile: tim dev AI-mu, dalam satu papan","index.description":"AI-gile adalah papan kanban untuk tim pemrograman AI. Mereka bekerja saat kamu tidur; kamu cukup mengurus satu tumpukan pendek: hal yang perlu diputuskan, dites, dan disetujui.","hero.logoAlt":"Ikon papan AI-gile","hero.h1.html":"Tim dev AI-mu, dalam satu&nbsp;papan.","hero.alpha":"🐣 Pra-alfa tertutup","hero.alphaTitle":"Masih awal dan belum selesai: terima kasih sudah mau mencoba!","hero.lede":"Mereka membangun selagi kamu tidur. Kamu bangun dan menemukan satu tumpukan pendek: beberapa pertanyaan, beberapa hal untuk dites, satu atau dua berlian ungu. Klik, setujui, lanjut ngopi.","dl.windows":"Aplikasi Windows","dl.browser":"Jalankan di browser","dl.messenger":"📱 Messenger untuk ponselmu","dl.soon":"Segera hadir","dl.notify":"🔔 Kabari aku saat dibuka","dl.notifySmall":"Alfa atau beta","hero.secondary":"Agile, tapi timnya tidak butuh kopi stand-up. (Stand-up tetap jalan, sih.)","pitch.h2":"AI-gile dalam sebanyak kata yang kamu mau","pitch.lede":"Pilih panjangnya, dari satu kata sampai 144. Setiap panjang punya deskripsinya sendiri, ditulis khusus untuk ukuran itu. Geser slider atau pakai tombol panah.","pitch.rangeLabel":"Panjang dalam kata","pitch.dice":"🎲 versi lain","pitch.words.one":"{n} kata","pitch.words.other":"{n} kata","pitch.letters.one":"{n} huruf","pitch.letters.other":"{n} huruf","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karakter","count.line.html.one":"{n} kartu di papan sekarang","count.line.html.other":"{n} kartu di papan sekarang","people.humans.html.one":"👥 {n} manusia","people.humans.html.other":"👥 {n} manusia","people.agents.html.one":"🤖 {n} agen","people.agents.html.other":"🤖 {n} agen","people.working.html.one":"⚡ {n} sedang bekerja sekarang","people.working.html.other":"⚡ {n} sedang bekerja sekarang","pre.title":"AI-gile: ada yang sedang dibangun","pre.description":"Ada sesuatu yang sedang dibangun di sini. Papan tempat tim AI membangun apa yang kamu minta, sambil mengajarimu di sepanjang jalan. Untuk sekarang, pra-alfa tertutup bersama teman-teman.","pre.h1":"Ada sesuatu yang sedang dibangun di sini. 🤫","pre.line":"Papan tempat tim AI membangun apa yang kamu minta, sambil mengajarimu di sepanjang jalan. Untuk sekarang, pra-alfa tertutup bersama teman-teman.","pre.btn":"🔔 Kabari aku saat dibuka","pre.peek":"Di balik kaca: papan yang asli, langsung. Setiap kartu adalah batang berwarna.","pre.peekFake":"Di balik kaca: seperti inilah papan yang sedang bekerja.","pre.night":"🌙 Penjaga malam yang memegang kendali · 😴 si manusia sedang istirahat","features.aria":"Apa yang dilakukannya","f.pile.h":"Satu tumpukan untukmu","f.pile.html":"<b>Untukmu</b> berisi semua yang menunggumu, dari semua proyek: pertanyaan, hal untuk dites, tugas yang hanya bisa dikerjakan manusia. Antreanmu memberi tahu apa yang berikutnya dan berapa lama.","f.sleep.h":"Tim yang bekerja saat kamu tidur","f.sleep.p":"Setiap proyek punya lead dan tim agen AI. Beri komentar di sebuah kartu, tim pun bangun, mengerjakannya, lalu mengembalikannya dengan langkah-langkah yang bisa diikuti manusia yang sedang capek.","f.tester.h":"Penguji AI memeriksa lebih dulu","f.tester.p":"Sebelum sampai ke kamu, penguji mengikuti langkah-langkahnya di salinan aplikasi dan menunjukkan apa yang dilihatnya, lengkap dengan tangkapan layar. Telusuri yang lolos dan setujui dengan satu klik.","f.proof.h":"Bukti, bukan janji","f.proof.p":"Setiap serah terima menunjukkan apa yang berubah: berkas, diff, tangkapan layar. Tidak perlu membuka satu per satu aplikasi untuk tahu sudah selesai atau belum.","f.chat.h":"Ngobrol dengan lead-mu","f.chat.p":"Bilah ala Discord: satu ikon per proyek, berlian ungu untuk yang butuh kamu. Kirim ide ke lead; ia mengubahnya jadi kartu dan rencana, dengan tombol ✅ Go.","f.tidy.h":"Rapi dengan sendirinya","f.tidy.p":"Kartu yang berkaitan digabung jadi satu, judul yang berantakan dibereskan, dan pemeriksaan token menjaga kode tetap ramping. Lebih sedikit yang harus dipindah-pindah, lebih sedikit yang harus dipikirkan.","f.private.h":"Milikmu, di komputermu","f.private.li1":"Papan berjalan di mesinmu sendiri dan hanya menjawab kamu.","f.private.li2":"Pesan pribadi antarmanusia dienkripsi ujung ke ujung.","f.private.li3":"Tanpa akun, tanpa pelacak, tanpa cookie.","f.lang.h":"Dalam bahasamu","f.lang.p":"Lebih dari 120 bahasa, dari Belanda, Wales, dan Jepang sampai bajak laut, Yoda, dan Klingon, dengan tombol cepat kembali ke bahasa Inggris untuk istilah industri.","f.service.h":"Dari ide menjadi layanan sungguhan","f.service.p":"Sudah membangun sesuatu dengan AI yang kini dipakai orang? Tandai sebagai layanan dan papan membantumu menjalankannya dengan baik: cek uptime, halaman status publik, insiden dengan laporan tertulis, perubahan yang perlu Go, cadangan yang dicek setiap hari. Bantuan mengajarkan setiap langkah sambil jalan.","msgr.h2":"AI-gile Messenger: timmu di dalam saku","msgr.p1":"Ngobrol dengan tim AI-mu tanpa membuka board. Chat dengan lead proyekmu dan teman-temanmu, lihat langkah tes sebuah kartu lalu jawab, semuanya dari ponselmu.","msgr.p2":"Untuk menyambungkannya, pindai kode QR di board-mu. Baru pertama kali? Chat demo yang ramah akan mengajakmu berkeliling.","msgr.when":"Android dulu, lalu versi web untuk ponsel dan iPhone.","msgr.who":"Lead proyekmu","msgr.b1":"Perbaikan mode gelap sudah siap. Mau langkah tesnya?","msgr.b2":"Mau dong!","msgr.b3":"1. Buka Pengaturan. 2. Pilih Gelap. Sudah kelihatan benar?","tl.aria":"Lini masa dari percakapan pertama sampai peta jalan","tl.h2":"Dari obrolan pertama sampai yang berikutnya","tl.lede":"Tanggal dan jam sungguhan, dalam zona waktumu sendiri. Setelah hari ini, itu baru rencana, tanpa janji tanggal.","tl.today":"Hari ini","tl.planned":"direncanakan","tl.doing":"dikerjakan","tl.cards.one":"{n} kartu","tl.cards.other":"{n} kartu","join.h2":"Ikut serta","join.lede":"AI-gile dibuat oleh seorang nyentrik berjenggot yang punya AuDHD dan beberapa pergulatan dengan kesehatan mental, serta banyak agen yang sabar. Untuk sekarang masih privat, alfa tertutup bersama teman-teman. Mau ikut coba saat dibuka?","join.btn":"Daftarkan minat","join.small":"Kami kirim email, tidak lebih","footer.tag":"AI-gile. Tanpa pelacak, tanpa cookie, tanpa kopi stand-up.","footer.licence":"Lisensi bisnis","footer.status":"Status","footer.privacy":"Apa yang kami simpan","footer.thanks":"Panggilan berkat ChilledChat","form.sending":"Mengirim…","form.failed":"Belum berhasil: coba lagi nanti.","form.offline":"AI-gile tidak terjangkau: coba lagi nanti.","form.keep":"Kami hanya memakai ini untuk membalasmu, lalu menghapusnya. Tanpa pelacak, tanpa cookie.","form.keepLink":"Apa yang kami simpan","interest.title":"AI-gile: kabari aku saat alfa dibuka","interest.description":"Tinggalkan emailmu untuk tahu kapan alfa atau beta tertutup AI-gile dibuka.","interest.h1":"🔔 Kabari aku saat dibuka","interest.lede":"AI-gile masih dalam pra-alfa tertutup. Tinggalkan emailmu dan kami akan menulis sekali, saat ada tempat untukmu.","interest.email":"Emailmu","interest.which":"Tes yang mana?","interest.alpha":"Alfa tertutup: awal, kasar, banyak perubahan","interest.beta":"Beta: lebih stabil, nanti","interest.both":"Salah satu, mana yang duluan","interest.submit":"Masukkan aku ke daftar","interest.thanks":"Terima kasih! Kamu sudah ada di daftar.","licence.title":"AI-gile: lisensi bisnis","licence.description":"Memakai AI-gile untuk bisnismu? Ajukan lisensi bisnis gratis.","licence.h1":"📜 Lisensi bisnis","licence.lede":"Memakai AI-gile di tempat kerja? Ceritakan siapa kamu dan apa yang kamu kerjakan. Kalau bermanfaat, lisensinya gratis.","licence.company":"Perusahaan","licence.website":"Situs web","licence.what":"Bidang usahamu","licence.how":"Bagaimana ini membantu dunia","licence.email":"Email","licence.submit":"Ajukan","licence.thanks":"Terima kasih! Kami akan membalas lewat email.","status.title":"Status AI-gile","status.h1":"Status AI-gile","status.quiet":"Semua tenang","status.intro":"Apakah AI-gile sedang berjalan? Halaman ini memeriksa situs web, berbagi papan, panggilan, dan unduhan setiap 5 menit.","status.up":"Berjalan (menjawab dalam {ms} ms)","status.slow":"Tidak menjawab pemeriksaan terakhir, mencoba lagi","status.down":"Mati: tidak menjawab dua pemeriksaan terakhir","status.svc.web":"Situs web","status.svc.web.offers":"Situs ini: apa itu AI-gile, dan formulir minat","status.svc.boards":"Berbagi papan","status.svc.boards.offers":"Papan publik, pesan antarteman, dan undangan","status.svc.calls":"Panggilan","status.svc.calls.offers":"Suara, video, dan berbagi layar di AI-gile","status.svc.download":"Unduhan","status.svc.download.offers":"Penginstal Windows dan tautan undangan","status.checking":"Memeriksa…","status.offline":"Layanan status belum terjangkau (mencoba lagi)","status.updated":"diperbarui {ago}","status.justNow":"baru saja","status.min":"{n} menit lalu","status.hours":"{n} jam lalu","status.days":"{n} hari lalu","privacy.title":"AI-gile: apa yang kami simpan","privacy.h1":"Apa yang kami simpan","privacy.lede":"Singkatnya: hanya yang kamu kirim ke kami, dan tidak lama.","privacy.only":"Hanya yang kamu kirim ke kami: yang kamu ketik di formulir, seperti emailmu. Tidak ada hal lain tentang dirimu.","privacy.sealed":"Datanya disegel sehingga server kami tidak bisa membacanya: di browsermu sebelum dikirim (di browser lama, begitu tiba). Hanya papan kami sendiri yang bisa membukanya.","privacy.server":"Data dihapus dari server begitu sampai di papan kami. Apa pun yang masih ada di sana setelah 30 hari tetap dihapus.","privacy.board":"Kami menyimpannya di papan kami hanya sampai kami membalasmu, lalu menghapusnya juga dari sana.","privacy.none":"Tanpa pelacak, tanpa cookie, tanpa analitik.","privacy.local":"Bahasa dan pilihan mode terang atau gelapmu tetap di browsermu sendiri. Tidak pernah dikirim ke kami.","privacy.ask":"Ingin dihapus lebih cepat? Balas email kami dan bilang saja.","live.h2":"Lihat proses pembuatannya, langsung","live.caption":"Setiap kartu disembunyikan: Anda melihat bentuk pekerjaannya, bukan kata-katanya.","live.watching.one":"langsung: {n} menonton","live.watching.other":"langsung: {n} menonton","live.last.now":"Kartu terakhir dipindahkan baru saja","live.last.min.one":"Kartu terakhir dipindahkan {n} menit lalu","live.last.min.other":"Kartu terakhir dipindahkan {n} menit lalu","live.last.hour.one":"Kartu terakhir dipindahkan {n} jam lalu","live.last.hour.other":"Kartu terakhir dipindahkan {n} jam lalu","live.last.day.one":"Kartu terakhir dipindahkan {n} hari lalu","live.last.day.other":"Kartu terakhir dipindahkan {n} hari lalu","live.offline":"Papan langsung sedang istirahat sebentar. Cek lagi nanti ya.","live.cols":"Backlog|Akan dikerjakan|Dikerjakan|Tim memeriksa|Giliranmu tes|Untuk tim|Selesai","footer.models":"AI-gile menjalankan model AI untukmu. Apa yang mereka katakan dan lakukan adalah tanggung jawab mereka, jadi periksa dulu sebelum kamu percaya.","privacy.ai.h":"Bagian AI","privacy.ai.models":"AI-gile adalah papannya. Pekerjaannya dilakukan oleh model AI dari perusahaan lain, seperti Claude, Codex, dan Gemini, memakai akunmu sendiri.","privacy.ai.check":"Apa yang mereka tulis dan lakukan berasal dari mereka, dan bisa saja salah. Periksa dulu sebelum kamu mengandalkannya atau merilisnya.","privacy.ai.files":"Mereka mengubah file dan menjalankan perintah di folder yang kamu hubungkan. Buat cadangan.","privacy.ai.send":"Apa yang kamu berikan ke model dikirim ke perusahaan yang menjalankannya, sesuai ketentuan mereka. Ketentuan dan biaya masing-masing berlaku.","privacy.ai.asis":"AI-gile adalah versi uji coba awal, diberikan apa adanya."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Didelegasikan."]},{"n":2,"texts":["Kanban robot.","Agen, tertata.","Ide, jadi."]},{"n":3,"texts":["Kanban untuk robot.","Ide jadi fitur.","Kanban agen gratis."]},{"n":5,"texts":["Papan kanban yang dijalankan agen.","Kamu menulis kartu. Agen membangun.","Gratis, lokal, teruji, agak konyol."]},{"n":8,"texts":["Papan kanban gratis tempat agen AI bekerja.","Tulis ide. Agen membangunnya. Kamu menyetujui.","Agile untuk satu manusia dan banyak robot sabar."]},{"n":13,"texts":["Papan kanban di komputermu, tempat agen AI mengambil kartu, mengerjakannya, lalu mengembalikannya padamu.","Tulis sebuah ide. Tim agen membangunnya, lalu seorang penguji memeriksanya sebelum sampai ke kamu.","Gratis, tanpa akun, tanpa pelacak: satu papan, beberapa robot, dan kamu yang memegang kendali."]},{"n":21,"texts":["AI-gile adalah papan kanban untuk bekerja bersama agen pemrograman AI. Mereka mengambil kartunya; kamu yang mengetes dan menyetujuinya.","Setiap proyek punya seorang lead dan tim agen AI. Beri komentar di kartu mana pun, dan tim langsung bekerja.","Papan tugas pribadi yang gratis dan berjalan di komputermu sendiri. Pekerjanya robot. Yang berkata ya adalah kamu."]},{"n":34,"texts":["Kamu menaruh ide di sebuah papan. Tim agen AI mengubahnya jadi fitur yang berfungsi, mengetesnya, lalu menyerahkannya kembali dengan langkah-langkah untuk dicoba. Tidak ada yang dianggap selesai sebelum kamu bilang begitu.","AI-gile adalah papan kanban buatan sendiri yang dibuat Rich dengan banyak bantuan dari agen-agen yang kini diurusnya. Gratis, berjalan di komputermu, dan dibagikan ke teman-teman, bukan dijual.","Bayangkan papan kanban biasa, dengan kolom dari Backlog sampai Selesai, hanya saja kartunya diambil oleh agen AI. Mereka melaporkan kemajuan, bertanya saat buntu, dan selalu menunggu acungan jempolmu."]},{"n":55,"texts":["AI-gile adalah papan kanban yang timnya terdiri dari agen AI. Setiap proyek punya lead yang merencanakan pekerjaan dan pembantu yang membangunnya. Saat sebuah fitur siap, penguji AI mencobanya dan mengambil tangkapan layar, lalu fitur itu mendarat di tumpukanmu. Setujui, atau beri komentar dan mereka mengerjakannya ulang.","Awalnya ini cara satu orang melacak banyak sesi pemrograman AI sekaligus, lalu tumbuh jadi papan sungguhan. Ia berjalan di mesinmu, tanpa akun, tanpa pelacak. Gratis untuk teman dan siapa pun yang penasaran. Ia juga belum selesai, jadi harap maklum kalau ada sisi kasar dan kejutan kecil.","Ini versi jujurnya. Kamu tetap harus punya ide, dan tetap harus memeriksa hasilnya. Yang dikerjakan AI-gile adalah semua yang ada di antaranya: menjaga kartu tetap urut, membangunkan agen yang tepat saat kamu berkomentar, menunjukkan persis apa yang berubah, dan menyimpan semuanya dalam satu tumpukan pendek untukmu."]},{"n":89,"texts":["AI-gile adalah papan kanban gratis yang kamu jalankan di komputermu sendiri. Alih-alih orang, setiap proyek punya tim agen AI: seorang lead yang mengubah ide-idemu jadi kartu dan rencana, dan pembantu yang mengambil kartu sesuai urutan prioritas. Setelah sesuatu selesai dibangun, penguji AI mengikuti langkah tesnya dan menunjukkan apa yang dilihatnya. Lalu hasilnya menunggu di satu tumpukan bernama Untukmu. Kamu menyetujuinya, atau memberi komentar dan tim mencoba sekali lagi. Tidak ada yang sampai ke Selesai tanpa kamu.","Beberapa fitur yang mungkin tak kamu duga. Penjaga malam mengisi kolom Akan dikerjakan selagi kamu tidur, dengan memilih kartu yang tidak butuh jawabanmu. Penghitung token menunjukkan berapa banyak yang dipakai agen hari ini dan minggu ini, dan Mode Tanpa Token menyuruh mereka berhenti menghabiskan. Kamu bisa berkirim pesan dengan teman, dan pesan pribadi dienkripsi ujung ke ujung. Papan ini berbahasa sekitar 120 bahasa, termasuk Belanda, Flemish, bajak laut, dan Klingon. Semuanya tanpa biaya sepeser pun, dan tak ada yang berusaha menjualnya padamu.","AI-gile adalah proyek kecil pribadi, bukan perusahaan. Rich ingin mengurus beberapa proyek pemrograman AI tanpa membuka tiap aplikasi untuk mengeceknya, jadi ia dan para agen membuat papan untuk itu, lalu memakai papan itu untuk membangun sisanya. Statusnya pra-alfa tertutup, artinya ia berfungsi, kurang lebih, untuk segelintir teman. Tidak ada halaman harga, tidak ada newsletter, dan tidak ada rencana pertumbuhan. Kalau kedengarannya berguna, kamu bisa minta mencobanya saat dibuka sedikit lebih lebar."]},{"n":144,"texts":["AI-gile adalah papan kanban untuk satu manusia dan banyak agen AI. Ia berjalan di komputermu sendiri dan sepenuhnya gratis. Kamu menambahkan proyek, dan setiap proyek mendapat lead beserta tim kecil. Kamu ngobrol dengan lead, agak mirip Discord, dan menjelaskan sebuah ide; lead mengubahnya jadi kartu dan rencana, lalu menunggu kamu menekan Go. Tim mengerjakan kartu sesuai urutan prioritas, memakai antarmuka baris perintah sederhana yang dibuat untuk model bahasa. Sebelum apa pun kembali kepadamu, penguji AI mengikuti langkah-langkahnya di salinan aplikasi dan melampirkan tangkapan layar. Pekerjaan yang selesai mendarat di tumpukanmu bersama berkas yang berubah dan diff-nya. Kamu menyetujuinya, atau meninggalkan komentar, lalu tim bangun dan mencoba lagi. Hanya kamu yang bisa memindahkan kartu ke Selesai.","Kira-kira begini sehari bersama AI-gile. Malam hari kamu meninggalkan beberapa komentar: tombol ini salah tempat, daftar itu harus diurutkan, bisakah ada mode gelap. Kamu pergi tidur. Para agen membaca komentarnya, membuat perubahan, mengetesnya, dan menyerahkannya kembali padamu. Kalau kolom Akan dikerjakan kosong, penjaga malam mengisinya dari backlog dengan kartu yang tidak butuh jawabanmu. Pagi harinya ada satu tumpukan pendek: beberapa pertanyaan dan beberapa hal untuk dicoba, masing-masing dengan langkah yang bisa diikuti orang mengantuk dan tangkapan layar yang membuktikannya berfungsi. Kamu menelusurinya, menyetujui yang bagus dan mengembalikan sisanya. Penghitung token menunjukkan pemakaiannya, dan Mode Tanpa Token siap untuk minggu-minggu hemat. Kalau ada yang kurang pas, tinggal komentar lagi dan siklusnya berulang. Lalu kamu sarapan, hal yang belum bisa dibantu para agen.","Pertama, apa yang bukan AI-gile. Ia bukan startup, tidak dijual, dan tak seorang pun mengumpulkan datamu. Ia papan gratis yang berjalan di komputermu, tanpa akun, tanpa pelacak, dan tanpa cookie. Yang ia adalah: satu tempat rapi untuk melihat semua proyek pemrograman AI sekaligus, dengan tim agen yang mengerjakan kartu dan kamu yang mengambil keputusan. Ia menggabungkan kartu yang berkaitan, membereskan judul yang berantakan, dan menjaga agar kodenya tetap ramping. Ia berbicara sekitar 120 bahasa, dari Belanda dan Flemish sampai bajak laut dan Klingon. Teman-teman bisa saling berkirim pesan, secara pribadi dan terenkripsi. Ia dibuat oleh Rich dan banyak agen yang sabar, kebanyakan dengan memakai dirinya sendiri. Statusnya pra-alfa tertutup, jadi di beberapa bagian masih kasar. Kalau kedengarannya seru, mintalah baik-baik dan kamu mungkin bisa masuk lebih awal."]}],"quips":{"1":"Satu kata. Berani. Mungkin terlalu berani.","3":"Tiga kata. Sudah lebih jujur daripada kebanyakan halaman produk.","8":"Delapan kata. Masih lebih pendek daripada satu stand-up.","21":"Panjangnya itu story point, omong-omong. Ya iyalah.","55":"Lima puluh lima kata. Dua kartu selesai selagi kamu membaca ini.","144":"Itu yang terpanjang. Tidak ada 233. Para agen sudah tidur."}},"timeline":{"first-idea.name":"Ide pertama","first-idea.line":"Percakapan pertama, sebelum ada satu baris kode pun.","first-board.name":"Papan pertama","first-board.line":"Papan yang melacak pembuatannya sendiri: kartu, kolom, seret dan lepas, proyek.","team-roles.name":"Tim dan peran","team-roles.line":"Profil agen, templat tim, ruang, dan siapa mengerjakan apa.","install.name":"Pemasangan dan rilis","install.line":"Satu zip yang bisa dipasang teman, pembaruan otomatis, kanal, dan kembali ke versi lama.","usage-saver.name":"Penghemat pemakaian","usage-saver.line":"Ukur biaya tiap proses, jaga kode tetap ramping, hemat batasmu.","friends.name":"Teman dan berbagi","friends.line":"Pesan pribadi, relai teracak, undangan, peran, dan proyek bersama.","languages.name":"Bahasa","languages.line":"Setiap teks layar dalam berkas bahasa, dimulai dari Belanda dan Flemish.","ai-tester.name":"Penguji AI","ai-tester.line":"Penguji memeriksa setiap serah terima lebih dulu dan menunjukkan apa yang dilihatnya.","website.name":"Situs web","website.line":"aigile.lol, teaser, dan lini masa ini.","streaming.name":"Obrolan dan streaming","streaming.line":"Discord, Twitch, OBS, mode streamer, GIF, dan emoji.","no-ai.name":"Edisi Tanpa AI","no-ai.line":"Papan untuk orang yang menulis kode tanpa AI, dan papan publik.","night-watch.name":"Penjaga malam","night-watch.line":"Seorang penjaga dan Scrum Master menjaga tim tetap fokus selagi kamu tidur.","p-more.name":"Yang lainnya","p-more.line":"Ide-ide kecil yang masih menunggu giliran.","p-android.name":"Ponsel dan Android","p-android.line":"Buka papanmu dari ponsel, lalu aplikasi Android asli.","p-release.name":"Alfa dan seterusnya","p-release.line":"Alfa tertutup, situs langsung, lalu beta.","p-languages.name":"Lebih banyak bahasa","p-languages.line":"130 bahasa, plus mode imersi untuk yang sedang belajar.","p-engines.name":"Lebih banyak mesin AI","p-engines.line":"Pilih Claude, Codex, Gemini, Copilot, atau Cursor untuk tiap agen.","p-pro.name":"Praktik profesional","p-pro.line":"Label risiko, gerbang merge, kartu insiden, dan pagar pengaman.","p-self.name":"Menjagamu","p-self.line":"Mode lelah, pengingat merawat diri, dan 4:20.","p-servers.name":"Server dan skala","p-servers.line":"Pengaturan server global, peran, dan perencanaan untuk berkembang.","p-livestream.name":"Tambahan streaming","p-livestream.line":"Obrolan Twitch, emoji kustom, dan tampilan langsung publik."},"words":{"button":"📖 Istilah industri","h":"📖 Istilah dijelaskan","intro":"Pelatihan gratis dengan bahasa sederhana: setiap istilah yang akan kamu temui, dari ide pertama sampai layanan yang diandalkan orang, dengan Agile, membangun, menjaganya tetap aman, dan bekerja dengan AI di sepanjang jalan.","search":"Cari kata…","none":"Tidak ada kata yang cocok.","close":"Tutup","count":{"one":"{count} istilah","other":"{count} istilah"},"groups":[{"id":"idea","name":"💡 Ide dan penelusuran"},{"id":"plan","name":"🗺️ Merencanakan pekerjaan"},{"id":"agile","name":"🔁 Cara kerja Agile"},{"id":"build","name":"🛠️ Membangun"},{"id":"test","name":"🧪 Pengujian dan kualitas"},{"id":"change","name":"🔀 Mengubah dengan aman"},{"id":"run","name":"🛎️ Menjalankan layanan"},{"id":"sec","name":"🔒 Keamanan dan privasi"},{"id":"ai","name":"🤖 Bekerja dengan AI"},{"id":"money","name":"💰 Uang dan lisensi"}],"list":[{"id":"discovery","g":"idea","word":"Discovery (penelusuran)","text":"Tahap awal untuk mencari tahu masalah mana yang layak diselesaikan dan untuk siapa, sebelum ada yang dibuat.","also":["fase discovery","tahap penelusuran","discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Pernyataan masalah","text":"Satu atau dua kalimat yang menyebut siapa yang punya masalah, apa masalahnya, dan mengapa penting, supaya semua orang mengarah ke hal yang sama.","also":["problem statement","pernyataan masalah","problem statements"]},{"id":"user","g":"idea","word":"Pengguna","text":"Orang yang memakai apa yang kamu buat. Kebutuhan merekalah tujuan pekerjaan ini.","also":["user","users","pengguna"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Pemangku kepentingan","text":"Siapa saja yang peduli pada hasil pekerjaan atau terdampak olehnya, seperti orang yang membiayai, memakai, atau mendukungnya.","also":["stakeholder","stakeholders","pemangku kepentingan"]},{"id":"persona","g":"idea","word":"Persona","text":"Tokoh rekaan tetapi realistis yang mewakili satu jenis pengguna, supaya tim bisa bertanya “apakah Sam akan merasa ini mudah?”","also":["persona","personas"]},{"id":"userresearch","g":"idea","word":"Riset pengguna","text":"Berbicara dengan dan mengamati orang sungguhan untuk mengetahui apa yang mereka butuhkan, bukan menebak-nebak.","also":["wawancara pengguna","user research","user interviews"]},{"id":"journey","g":"idea","word":"Perjalanan pengguna","text":"Langkah-langkah yang diambil seseorang untuk menyelesaikan sesuatu, dari pertama kali mendengar tentangnya sampai selesai, termasuk di luar produkmu. Menggambarnya menunjukkan di mana mereka tersendat.","also":["user journey","user journeys","customer journey","perjalanan pelanggan"]},{"id":"painpoint","g":"idea","word":"Titik masalah","text":"Sesuatu yang mengganggu atau memperlambat orang saat ini. Produk yang bagus menghilangkan titik masalah.","also":["pain point","pain points","titik masalah"]},{"id":"assumption","g":"idea","word":"Asumsi","text":"Sesuatu yang kamu yakini tetapi belum diperiksa. Menuliskan asumsi menunjukkan apa yang perlu diuji lebih dulu.","also":["asumsi","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hipotesis","text":"Dugaan terbaik yang kamu rencanakan untuk diperiksa, beserta apa yang kamu harapkan terjadi, misalnya “orang akan mendaftar kalau bulan pertama gratis”.","also":["hipotesis","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Eksperimen","text":"Uji coba kecil yang terencana untuk mengetahui apakah sebuah ide berhasil, sebelum mempertaruhkan banyak hal padanya.","also":["eksperimen","experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"Percobaan cepat dan kasar untuk melihat apakah sebuah ide bisa berjalan sama sekali. Biasanya dibuang setelah jawabannya didapat.","also":["PoC","proof of concept","bukti konsep"]},{"id":"prototype","g":"idea","word":"Prototipe","text":"Model awal produk, sering berupa gambar yang bisa diklik, untuk mencoba ide kepada orang sebelum dibangun dengan benar.","also":["prototype","prototypes","prototipe"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Sketsa sederhana sebuah layar yang menunjukkan letak setiap elemen, tanpa warna atau isi sungguhan.","also":["wireframe","wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Gambar terperinci tentang tampilan sebuah layar nanti, dengan warna dan teks sungguhan, tetapi belum ada yang berfungsi.","also":["mockup","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"Alasan untuk menjalankan sebuah proyek: biayanya, apa yang dihasilkan atau dihemat, dan risikonya.","also":["business case","business cases","studi kelayakan bisnis"]},{"id":"feasibility","g":"idea","word":"Kelayakan","text":"Apakah sesuatu benar-benar bisa dibuat dan dirawat dengan waktu, uang, dan keahlian yang kamu punya.","also":["feasibility","layak"]},{"id":"outcome","g":"idea","word":"Outcome (dampak)","text":"Perubahan nyata yang kamu inginkan bagi orang, misalnya lebih sedikit janji temu yang terlewat. Dampak inilah yang penting, bukan seberapa banyak yang kamu buat.","also":["outcome","outcomes","dampak","hasil akhir"],"noTip":1},{"id":"output","g":"idea","word":"Output (keluaran)","text":"Barang yang dibuat tim, seperti layar baru atau laporan. Membuatnya belum tentu membawa dampak bagi siapa pun.","also":["output","outputs","keluaran"],"noTip":1},{"id":"successmetric","g":"idea","word":"Metrik keberhasilan","text":"Angka yang memberi tahu apakah pekerjaan mencapai tujuannya, misalnya lebih banyak orang menyelesaikan pesanan mereka.","also":["success metric","success metrics","metrik keberhasilan"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"Angka penting yang kamu pantau untuk melihat apakah semuanya berjalan baik, misalnya jumlah pendaftar per minggu.","also":["KPI","KPIs","key performance indicator","indikator kinerja utama"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKR)","text":"Cara menetapkan tujuan: objective menyatakan apa yang kamu inginkan, dan beberapa key result adalah angka yang menunjukkan kamu sudah mencapainya.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Produk","text":"Sesuatu yang dibuat dan dirawat untuk penggunanya, seperti aplikasi, situs web, atau alat.","also":["produk","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Visi produk","text":"Pernyataan singkat tentang siapa yang dibantu produk dan ke mana arahnya dalam jangka panjang.","also":["vision statement","product vision","pernyataan visi"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"Orang yang memutuskan apa yang dibuat dan dalam urutan apa, sehingga tim selalu mengerjakan hal yang paling penting. Di AI-gile, itu kamu.","also":["PO","product owners","pemilik produk"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"Orang yang mengurus arah sebuah produk: masalah apa yang diselesaikannya, untuk siapa, dan mengapa. PM juga bisa berarti project manager, jadi pastikan yang mana.","also":["product managers","manajer produk"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"Orang yang menjaga proyek tetap tepat waktu dan sesuai anggaran, mencatat siapa mengerjakan apa dan kapan.","also":["project managers","manajer proyek"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"Rencana kasar tentang apa yang akan datang dalam beberapa bulan ke depan, berurutan. Ia menunjukkan arah, bukan tanggal pasti, dan berubah seiring kamu belajar.","also":["roadmap","roadmaps","peta jalan"]},{"id":"milestone","g":"plan","word":"Milestone","text":"Titik dalam proyek yang layak ditandai, seperti “versi pertama tayang” atau “100 pengguna”.","also":["milestone","milestones","tonggak"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"Versi produk terkecil yang tetap berguna bagi orang sungguhan, sehingga kamu bisa belajar dari mereka sejak dini.","also":["MVP","MVPs","minimum viable product","produk minimum yang layak"]},{"id":"requirement","g":"plan","word":"Kebutuhan","text":"Sesuatu yang harus bisa dilakukan atau dimiliki produk yang sudah jadi.","also":["requirement","requirements","persyaratan"],"noTip":1},{"id":"scope","g":"plan","word":"Scope (lingkup)","text":"Apa yang termasuk dalam pekerjaan dan, sama pentingnya, apa yang tidak.","also":["lingkup","ruang lingkup","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"Ketika semakin banyak hal ditambahkan sedikit demi sedikit tanpa ada yang menyepakati tambahan waktu atau biayanya, sehingga pekerjaan tak pernah benar-benar selesai.","also":["feature creep","scope creep"]},{"id":"feature","g":"plan","word":"Fitur","text":"Satu hal yang bisa dilakukan produk untuk orang, seperti “atur ulang kata sandi”.","also":["fitur","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Pekerjaan besar yang terlalu besar untuk sekali kerja, sehingga dipecah menjadi kartu-kartu yang lebih kecil.","also":["epic","epics"]},{"id":"story","g":"plan","word":"User story","text":"Pekerjaan kecil yang ditulis dari sisi pengguna: “Sebagai pembeli, aku ingin menyimpan keranjangku, supaya bisa menyelesaikannya nanti.” Ini memulai percakapan tentang apa yang akan dibuat.","also":["user story","user stories","cerita pengguna"]},{"id":"ac","g":"plan","word":"Kriteria penerimaan (AC)","text":"Pemeriksaan yang harus dilewati sebuah kartu agar dianggap selesai, disepakati sebelum pekerjaan dimulai, misalnya “keranjang masih ada setelah aku keluar lalu masuk lagi”.","also":["AC","acceptance criteria","kriteria penerimaan"]},{"id":"task","g":"plan","word":"Tugas","text":"Satu pekerjaan yang harus dilakukan, sering berupa satu langkah kecil dari story yang lebih besar.","also":["task","tasks","tugas"],"noTip":1},{"id":"ticket","g":"plan","word":"Tiket","text":"Sebutan lain untuk kartu: satu pekerjaan atau satu permintaan yang dilacak dari awal sampai selesai.","also":["tiket","ticket","tickets"]},{"id":"priority","g":"plan","word":"Prioritas","text":"Seberapa penting atau mendesak sesuatu dibanding yang lain, sehingga pekerjaan terpenting didahulukan.","also":["prioritas","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Penentuan prioritas","text":"Mengurutkan pekerjaan menurut tingkat kepentingan. Cara yang umum adalah MoSCoW: Must have (harus ada), Should have (sebaiknya ada), Could have (boleh ada), Won’t have (tidak kali ini).","also":["memprioritaskan","MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimasi","text":"Dugaan terbaik tentang seberapa besar atau seberapa lama sebuah pekerjaan. Itu dugaan, bukan janji.","also":["perkiraan","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story point","text":"Cara menebak ukuran pekerjaan dengan membandingkan kartu satu sama lain (“kira-kira dua kali lebih besar dari yang itu”), bukan dalam jam. Bukan untuk membandingkan antartim.","also":["story points","story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Menebak ukuran pekerjaan sebagai S, M, L, atau XL. Cepat dan cukup baik untuk perencanaan awal.","also":["ukuran kaus","t-shirt sizing","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Permainan untuk memperkirakan: semua orang menunjukkan kartu ukuran pada saat yang sama, lalu yang tertinggi dan terendah menjelaskan alasannya.","also":["Scrum poker","planning poker"]},{"id":"dependency","g":"plan","word":"Ketergantungan","text":"Ketika satu pekerjaan tak bisa dimulai atau selesai sebelum pekerjaan lain selesai.","also":["dependensi","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Apa pun yang menghentikan pekerjaan maju saat ini, seperti jawaban yang belum datang atau alat yang rusak.","also":["penghambat","hambatan","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Tenggat","text":"Tanggal paling lambat sesuatu harus selesai.","also":["deadline","deadlines","tenggat waktu"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable (hasil serahan)","text":"Keluaran konkret yang dihasilkan pekerjaan lalu diserahkan, seperti halaman yang berfungsi atau sebuah laporan.","also":["deliverable","deliverables","hasil serahan"]},{"id":"forecast","g":"plan","word":"Prakiraan","text":"Perkiraan tentang apa yang mungkin terjadi, misalnya kapan pekerjaan selesai, berdasarkan apa yang kamu ketahui sejauh ini.","also":["forecast","forecasts","prakiraan"],"noTip":1},{"id":"metric","g":"plan","word":"Metrik","text":"Apa pun yang kamu ukur dan pantau dari waktu ke waktu, seperti kunjungan halaman atau lama perbaikan.","also":["metric","metrics","metrik"]},{"id":"feedback","g":"plan","word":"Umpan balik","text":"Apa yang orang katakan tentang pekerjaanmu, baik dan buruk. Mendapatkannya sejak dini dan sering adalah inti Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Daftar tunggu ide dan pekerjaan yang belum direncanakan, yang terpenting di atas. Tidak ada yang dikerjakan di sana sampai dipindah ke Akan dikerjakan."},{"id":"sprint","g":"agile","word":"Sprint","text":"Rentang kerja singkat dan tetap (sering satu atau dua minggu, tidak pernah lebih dari sebulan) dengan sebuah tujuan dan sekumpulan kartu yang disepakati untuk diselesaikan.","also":["sprint"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Cek harian singkat: apa yang dikerjakan tiap anggota tim, apa yang dikerjakan berikutnya, dan apa yang menghambat. Di Scrum disebut daily scrum.","also":["standup","stand-ups","daily scrum","daily stand-up","rapat harian"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Cara kerja saat kartu bergerak melintasi kolom board (seperti Akan dikerjakan, Dikerjakan, Selesai) dan tim membatasi seberapa banyak yang dikerjakan sekaligus, supaya pekerjaan terus mengalir."},{"id":"wip","g":"agile","word":"Batas WIP","text":"WIP singkatan dari work in progress (pekerjaan yang sedang berjalan). Batas WIP adalah jumlah kartu terbanyak yang sebaiknya ada di satu kolom sekaligus, supaya tim menyelesaikan sesuatu sebelum memulai yang lain.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Daftar periksa singkat tim tentang arti “selesai”, misalnya sudah dites dan dijelaskan, sebelum kartu diserahkan kepadamu. Kembarannya, Definition of Ready, menyatakan kapan kartu cukup jelas untuk dimulai.","also":["Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"Tinjauan rutin tentang cara kerja tim, untuk menyepakati satu atau dua hal yang akan dilakukan lebih baik lain kali. Singkatan dari retrospective. Di AI-gile, retro menyarankan perubahan pada cara kerja tim, dan kamu menjawab Go atau Belum.","also":["retrospektif","retrospective"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Semua turun tangan: banyak orang meninggalkan pekerjaan lain untuk memperbaiki satu hal mendesak bersama-sama sampai beres. Di AI-gile semua tim membantu satu proyek, sementara proyek lain menunggu.","also":["swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Di Scrum, orang yang membantu tim bekerja dengan baik: menyingkirkan hambatan, menjaga pertemuan tetap pada jalurnya, dan melatih kebiasaan baik, tanpa memerintah siapa pun. Di AI-gile, Lead Scrum Master mengenali kartu yang macet, menyentil tim, dan mengingatkanmu pada apa yang menunggu, di semua proyek.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Cara bekerja dalam langkah-langkah kecil: bangun sedikit, tunjukkan hasil nyata sering-sering, belajar dari ucapan orang, dan ubah rencana sambil jalan, bukan merencanakan semuanya di awal.","also":["Agile development","agile ways of working","pengembangan agile"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"Pernyataan singkat yang ditulis pada 2001 oleh para pembuat perangkat lunak. Isinya mengutamakan manusia, hasil yang berfungsi, kerja sama erat dengan pelanggan, dan tanggap terhadap perubahan di atas rencana dan dokumen yang berat.","also":["Manifesto for Agile Software Development","manifesto agile"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"Cara kerja gaya lama: rencanakan semuanya, lalu bangun semuanya, lalu uji semuanya, satu tahap demi satu tahap. Perubahan di akhir sulit dan mahal.","also":["waterfall","waterfall model","model air terjun"]},{"id":"iteration","g":"agile","word":"Iterasi","text":"Satu putaran membangun sesuatu, memeriksanya, dan memperbaikinya. Kerja Agile adalah rangkaian putaran seperti ini, dan sprint adalah salah satu jenisnya.","also":["iteration","iterations","iterasi"]},{"id":"increment","g":"agile","word":"Increment","text":"Bagian baru yang berfungsi yang ditambahkan ke produk dalam satu sprint atau putaran kerja, dan cocok dengan yang sudah ada.","also":["increment","increments","inkremen"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Cara kerja Agile yang populer: tim kecil bekerja dalam sprint singkat menuju sebuah tujuan, dengan peran tertentu dan beberapa pertemuan rutin untuk merencanakan, memeriksa, dan memperbaiki."},{"id":"scrumteam","g":"agile","word":"Tim Scrum","text":"Kelompok kecil yang mengerjakan pekerjaan dalam Scrum: product owner, Scrum Master, dan para developer.","also":["Scrum team","Scrum teams","tim scrum"]},{"id":"ceremonies","g":"agile","word":"Event Scrum","text":"Pertemuan rutin dalam Scrum: sprint planning, daily scrum, sprint review, dan retro. Banyak orang menyebutnya seremoni.","also":["ceremonies","Scrum ceremonies","seremoni","seremoni Scrum"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"Pertemuan di awal sprint saat tim menyepakati mengapa sprint itu penting, kartu mana yang diambil, dan bagaimana memulainya.","also":["planning meeting","rapat perencanaan"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"Satu kalimat yang menyatakan untuk apa sebuah sprint. Tugas-tugas kecil boleh berubah di tengah jalan, asalkan tujuannya tercapai.","also":["sprint goal","sprint goals","tujuan sprint"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"Kartu-kartu yang dipilih untuk sprint saat ini, beserta rencana tim untuk mengerjakannya.","also":["sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"Daftar berurutan lengkap dari semua yang mungkin dibuat untuk produk, yang terpenting di atas. Daftar ini terus berubah seiring kamu belajar.","also":["product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"Hasil lebih besar yang dituju produk, yang membantu tim memilih apa yang dikerjakan berikutnya.","also":["product goal","product goals","tujuan produk"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Menelusuri backlog secara berkala untuk merapikan, memecah, mengurutkan, dan menambah detail pada kartu, supaya siap diambil. Disebut juga backlog grooming.","also":["backlog grooming","refinement","penyempurnaan backlog"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"Pertemuan di akhir sprint saat tim menunjukkan apa yang selesai dan mendengar pendapat orang, untuk memutuskan apa yang berikutnya.","also":["sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Memperlihatkan secara langsung pekerjaan yang sudah selesai dan berfungsi kepada orang yang memintanya.","also":["demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"Jumlah waktu tetap untuk sesuatu. Saat waktunya habis kamu berhenti, meskipun belum semuanya selesai.","also":["timebox","timeboxed","timeboxes","batas waktu"]},{"id":"velocity","g":"agile","word":"Velocity","text":"Berapa banyak pekerjaan yang biasanya diselesaikan tim dalam satu sprint, dipakai untuk merencanakan seberapa banyak yang diambil berikutnya. Bukan nilai seberapa keras orang bekerja.","also":["velocity","team velocity","kecepatan tim"]},{"id":"capacity","g":"agile","word":"Kapasitas","text":"Seberapa banyak pekerjaan yang bisa diambil tim dalam suatu periode, setelah dikurangi libur dan tugas lain.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"Grafik sisa pekerjaan dalam sprint yang turun hari demi hari. Kalau garisnya datar, ada yang macet.","also":["burndown","burndown chart","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"Grafik pekerjaan yang selesai naik dari waktu ke waktu, di samping total yang direncanakan, sehingga kamu bisa melihat kapan akan sampai.","also":["burnup","burnup chart","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Papan Kanban","text":"Board itu sendiri: satu kolom untuk setiap tahap pekerjaan, dengan kartu-kartu yang bergerak melintasinya.","also":["Kanban board","Kanban boards","board Kanban"]},{"id":"pullsys","g":"agile","word":"Sistem tarik (pull system)","text":"Cara kerja yang baru memulai pekerjaan baru saat ada orang yang punya ruang untuk mengambilnya, bukan mendorongnya ke piring yang sudah penuh.","also":["pull system","pull-based","sistem pull"]},{"id":"flow","g":"agile","word":"Flow (aliran kerja)","text":"Seberapa lancar pekerjaan bergerak di board. Flow yang baik berarti kartu terus bergerak, tidak menumpuk.","also":["aliran kerja","flow","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"Berapa lama dari seseorang meminta sesuatu sampai selesai.","also":["lead time","lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"Berapa lama sebuah kartu dari saat pekerjaan benar-benar dimulai sampai selesai.","also":["cycle time","cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"Berapa banyak kartu yang selesai dalam seminggu, atau dalam jangka waktu tertentu.","also":["throughput","throughput rate","laju selesai"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"Satu tahap tempat pekerjaan menumpuk dan memperlambat semua yang ada di belakangnya, seperti leher botol yang sempit.","also":["bottleneck","bottlenecks","leher botol"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"Baris melintang di board yang mengelompokkan kartu sejenis, seperti pekerjaan mendesak atau kartu satu tim.","also":["swimlane","swimlanes","swim lane","jalur"]},{"id":"lean","g":"agile","word":"Lean","text":"Cara kerja yang membuang pemborosan (apa pun yang tidak membantu pelanggan) dan menjaga pekerjaan tetap mengalir."},{"id":"waste","g":"agile","word":"Pemborosan","text":"Dalam Lean, apa pun yang memakan tenaga tetapi tidak membantu pelanggan, seperti menunggu, mengerjakan ulang, atau membuat hal yang tak dipakai siapa pun.","noTip":1},{"id":"kaizen","g":"agile","word":"Perbaikan berkelanjutan","text":"Menjadi sedikit lebih baik setiap saat lewat perubahan kecil yang rutin, lalu memeriksa apakah membantu. Retro adalah salah satu caranya. Disebut juga kaizen.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Tim yang mengatur diri sendiri","text":"Tim yang memutuskan sendiri cara mengerjakan pekerjaan, bukan disuruh langkah demi langkah.","also":["self-organising","self-organizing","self-organising team","self-managing team","tim swakelola"]},{"id":"crossfunc","g":"agile","word":"Tim lintas fungsi","text":"Tim yang memiliki semua keahlian untuk menyelesaikan pekerjaan sendiri, seperti desain, pembuatan, dan pengujian.","also":["cross-functional","cross-functional team"]},{"id":"spike","g":"agile","word":"Spike","text":"Riset singkat berbatas waktu untuk menjawab sebuah pertanyaan sebelum berkomitmen pada pekerjaan yang sebenarnya.","also":["spike","spikes"]},{"id":"rework","g":"agile","word":"Pekerjaan ulang","text":"Mengerjakan lagi karena yang pertama kali belum benar.","also":["rework","reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Cara menerapkan Agile di banyak tim dalam organisasi besar. SAFe (Scaled Agile Framework) adalah salah satu contoh yang terkenal.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Folder kode proyek beserta riwayat lengkap commit-nya. Bisa berada di komputermu, di GitHub, atau keduanya.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Jalur kerja terpisah di dalam kode, supaya perubahan bisa dibuat tanpa menyentuh versi utama.","also":["branch","cabang"]},{"id":"commit","g":"build","word":"Commit","text":"Cuplikan kode yang tersimpan, dengan catatan singkat tentang apa yang berubah. Kamu selalu bisa kembali ke salah satunya.","also":["commit"]},{"id":"push","g":"build","word":"Push","text":"Mengirim snapshot yang kamu simpan (commit) dari komputer ini ke salinan bersama online, seperti GitHub, sehingga tercadangkan dan orang lain bisa mengambilnya."},{"id":"merge","g":"build","word":"Merge","text":"Menggabungkan perubahan dari satu branch ke branch lain, biasanya kembali ke versi utama."},{"id":"pr","g":"build","word":"Pull request","text":"Meminta agar perubahan sebuah branch diperiksa dan digabung ke versi utama. Beberapa situs menyebutnya merge request.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Merapikan kode tanpa mengubah fungsinya: file lebih kecil, nama lebih jelas, lebih sedikit pengulangan."},{"id":"bug","g":"build","word":"Bug","text":"Sesuatu yang tidak berfungsi sebagaimana mestinya.","also":["bug"]},{"id":"peerreview","g":"build","word":"Peer review","text":"Sepasang mata lain: seseorang selain penulisnya memeriksa pekerjaan sebelum sampai kepadamu, sehingga lebih sedikit kesalahan lolos. Di AI-gile, AI lain memeriksa setiap kartu.","also":["code review","tinjauan sejawat"]},{"id":"code","g":"build","word":"Kode","text":"Instruksi tertulis yang memberi tahu komputer apa yang harus dilakukan. Disebut juga kode sumber.","also":["kode","source code","kode sumber","code"],"noTip":1},{"id":"proglang","g":"build","word":"Bahasa pemrograman","text":"Bahasa untuk menulis kode, seperti JavaScript, Python, atau Java. Masing-masing cocok untuk pekerjaan yang berbeda.","also":["programming language","programming languages","bahasa pemrograman"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Orang yang menulis dan mengubah kode. Disebut juga programmer atau software engineer.","also":["developer","developers","programmer","programmers","software engineer","pengembang"]},{"id":"software","g":"build","word":"Perangkat lunak","text":"Program yang berjalan di komputer dan ponsel, berbeda dari mesinnya sendiri (perangkat keras).","noTip":1},{"id":"app","g":"build","word":"Aplikasi","text":"Program yang dipakai orang untuk menyelesaikan sesuatu, di ponsel, komputer, atau peramban web.","also":["app","apps","application","applications","aplikasi"],"noTip":1},{"id":"webapp","g":"build","word":"Aplikasi web","text":"Aplikasi yang berjalan di peramban web, jadi tidak ada yang perlu dipasang.","also":["web app","web apps","web application","aplikasi web"]},{"id":"frontend","g":"build","word":"Front end","text":"Bagian aplikasi yang kamu lihat dan klik: layar, tombol, dan kata-katanya, sering di peramban.","also":["front-end","frontend","front end","sisi depan"]},{"id":"backend","g":"build","word":"Back end","text":"Bagian aplikasi di balik layar yang menyimpan data dan bekerja saat kamu mengeklik sesuatu, seperti memeriksa kata sandimu.","also":["back-end","backend","back end","sisi belakang"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Mengerjakan front end maupun back end.","also":["full-stack","full stack"]},{"id":"ui","g":"build","word":"Antarmuka pengguna (UI)","text":"Apa yang dilihat dan dipakai seseorang di layar: tata letak, tombol, menu, dan teks.","also":["UI","user interface","antarmuka"]},{"id":"ux","g":"build","word":"Pengalaman pengguna (UX)","text":"Bagaimana rasanya memakai sesuatu: mudah, jelas, dan menyenangkan, atau membingungkan dan lambat.","also":["UX","user experience","pengalaman pengguna"]},{"id":"accessibility","g":"build","word":"Aksesibilitas (a11y)","text":"Membuat sesuatu bisa dipakai semua orang, termasuk yang penglihatannya kurang baik, tak bisa memakai mouse, atau memakai pembaca layar.","also":["a11y","accessibility","aksesibilitas"]},{"id":"responsive","g":"build","word":"Desain responsif","text":"Membuat halaman pas dan nyaman di ukuran layar apa pun, dari ponsel sampai monitor besar.","also":["responsif","desain responsif"]},{"id":"designsys","g":"build","word":"Design system","text":"Perangkat bersama berisi warna, huruf, tombol, dan aturan, sehingga setiap layar tampil dan berperilaku sama.","also":["design system","design systems","sistem desain"]},{"id":"architecture","g":"build","word":"Arsitektur","text":"Bentuk keseluruhan sebuah sistem: apa bagian-bagian utamanya dan bagaimana mereka saling berkomunikasi."},{"id":"database","g":"build","word":"Basis data (DB)","text":"Penyimpanan informasi yang tertata, seperti spreadsheet yang sangat kuat yang bisa dibaca dan diubah aplikasi.","also":["database","databases","DB","basis data"]},{"id":"schema","g":"build","word":"Skema basis data","text":"Tata letak sebuah basis data: tabel informasi apa saja yang dimilikinya dan apa isi masing-masing.","also":["schema","skema"]},{"id":"sql","g":"build","word":"SQL","text":"Singkatan dari structured query language: bahasa yang dipakai untuk meminta informasi dari banyak basis data atau mengubahnya.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Informasi yang disimpan komputer, seperti nama, pesanan, atau pengaturan.","also":["dataset","datasets","kumpulan data"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Komputer yang selalu menyala dan menjawab permintaan dari komputer lain, seperti mengirim halaman web saat kamu mengunjunginya.","also":["server","servers"]},{"id":"client","g":"build","word":"Klien","text":"Pihak yang meminta sesuatu, biasanya peramban atau aplikasimu, yang berbicara dengan server. Dalam bisnis, artinya juga sekadar pelanggan.","also":["client","clients","klien"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Singkatan dari application programming interface: menu permintaan tetap yang bisa diajukan satu program ke program lain, seperti meminta layanan cuaca untuk prakiraan hari ini.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Satu butir di menu sebuah API: alamat web yang bisa dipanggil program untuk mengambil atau mengirim sesuatu.","also":["endpoint","endpoints"]},{"id":"integration","g":"build","word":"Integrasi","text":"Menghubungkan dua sistem agar bekerja bersama, seperti tokomu mengirim pesanan ke perangkat lunak akuntansimu.","also":["integration","integrations","integrasi"]},{"id":"webhook","g":"build","word":"Webhook","text":"Pesan yang dikirim satu sistem ke sistem lain dengan sendirinya begitu sesuatu terjadi, seperti “pembayaran diterima”.","also":["webhook","webhooks"]},{"id":"library","g":"build","word":"Library","text":"Kode siap pakai buatan orang lain yang bisa kamu pakai ulang daripada menulisnya sendiri.","also":["library","libraries","pustaka"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Struktur siap pakai untuk membangun aplikasi yang menentukan sebagian besar tata letak kode, seperti rangka rumah yang kamu isi.","also":["framework","frameworks","kerangka kerja"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"Kotak berisi alat, kode, dan contoh untuk membuat perangkat lunak bagi satu platform atau layanan.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Dependensi perangkat lunak","text":"Library atau alat yang dibutuhkan kodemu agar berfungsi. Menjaganya tetap mutakhir penting demi keamanan.","also":["software dependency","software dependencies","dependensi"]},{"id":"package","g":"build","word":"Paket","text":"Kumpulan kode siap pakai yang bisa kamu pasang dan gunakan di sebuah proyek.","also":["package","packages","paket"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"Alat yang mengambil dan memperbarui paket yang dibutuhkan kodemu. npm adalah salah satu yang umum.","also":["package manager","package managers","npm","pengelola paket"]},{"id":"git","g":"build","word":"Git","text":"Alat yang paling banyak dipakai untuk menyimpan riwayat perubahan kode, berupa commit dan branch."},{"id":"github","g":"build","word":"GitHub","text":"Situs web yang menyimpan repo Git secara online, sehingga tim bisa berbagi kode, meninjau perubahan, dan melacak pekerjaan."},{"id":"vcs","g":"build","word":"Kontrol versi","text":"Menyimpan riwayat lengkap setiap perubahan pada file, sehingga kamu bisa melihat siapa mengubah apa dan kembali jika perlu. Git melakukan ini.","also":["source control","version control","version control system","kontrol sumber"]},{"id":"clone","g":"build","word":"Clone","text":"Membuat salinan penuh repo milikmu sendiri di komputermu, lengkap dengan riwayatnya.","also":["clone","cloned","cloning","mengkloning"]},{"id":"pull","g":"build","word":"Pull","text":"Mengambil commit terbaru dari salinan bersama (seperti GitHub) ke komputermu. Kebalikan dari push.","also":["git pull","pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Branch utama","text":"Versi resmi kode yang menjadi acuan semua orang, sering disebut main atau master.","also":["master branch","main branch","branch main"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"Ketika dua perubahan menyentuh baris yang sama dengan cara berbeda, sehingga komputer tak bisa menggabungkannya dan seseorang harus memilih.","also":["merge conflict","merge conflicts","konflik merge"]},{"id":"diff","g":"build","word":"Diff","text":"Tampilan yang menunjukkan persis apa yang berubah di antara dua versi: baris yang ditambah dan baris yang dihapus.","also":["diff","diffs","perbedaan"]},{"id":"fork","g":"build","word":"Fork","text":"Salinan repo orang lain milikmu sendiri, yang bisa kamu ubah tanpa memengaruhi repo mereka.","also":["fork","forks","forked"]},{"id":"script","g":"build","word":"Skrip","text":"Program pendek yang mengerjakan satu tugas sendiri, seperti merapikan file atau menjalankan aplikasi.","also":["script","scripts","skrip"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Mengubah kode menjadi sesuatu yang siap dijalankan, atau hasil siap jalan itu sendiri.","also":["build","builds"],"noTip":1},{"id":"compile","g":"build","word":"Kompilasi","text":"Menerjemahkan kode yang ditulis manusia ke bentuk yang bisa langsung dijalankan komputer.","also":["compile","compiler","mengompilasi"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"Jendela teks tempat kamu mengetik instruksi untuk komputer, bukan mengeklik. Disebut juga terminal.","also":["command line","command-line","CLI","terminal","baris perintah"]},{"id":"config","g":"build","word":"Konfigurasi (config)","text":"Pengaturan yang mengendalikan perilaku perangkat lunak, disimpan terpisah dari kode sehingga mudah diubah.","also":["config","configuration","konfigurasi"],"noTip":1},{"id":"envvar","g":"build","word":"Variabel lingkungan","text":"Pengaturan yang diberikan ke program saat dimulai, sering dipakai untuk alamat atau kata sandi agar tidak ditulis di dalam kode.","also":["environment variable","environment variables","env var","variabel lingkungan"]},{"id":"debugging","g":"build","word":"Debugging","text":"Mencari tahu mengapa sesuatu tidak berfungsi, lalu memperbaikinya.","also":["debug","debugged","debugging"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Dua orang (atau seseorang dan sebuah AI) mengerjakan kode yang sama bersama-sama, satu mengetik dan satu memeriksa.","also":["pairing","pair programming"]},{"id":"docs","g":"build","word":"Dokumentasi (docs)","text":"Penjelasan tertulis tentang cara kerja sesuatu atau cara memakainya.","also":["documentation","docs","dokumentasi"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"File pertama yang dibaca di sebuah repo: apa proyeknya dan cara menjalankannya.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Sistem lawas (legacy)","text":"Sistem lama yang masih dipakai dan sulit diubah, sering karena hanya sedikit orang yang masih memahaminya.","also":["legacy system","legacy systems","legacy code","sistem lawas"]},{"id":"techdebt","g":"build","word":"Utang teknis","text":"Jalan pintas yang menghemat waktu sekarang tetapi memperlambat perubahan nanti, seperti pinjaman yang bunganya menumpuk. Refactoring melunasinya.","also":["technical debt","tech debt","utang teknis"]},{"id":"test","g":"test","word":"Tes","text":"Pemeriksaan bahwa sesuatu berfungsi sebagaimana mestinya. Sebagian tes dijalankan komputer sendiri setiap kali kode berubah; yang lain adalah kamu mencoba kartu yang sudah jadi sebelum menerimanya.","also":["tes","test"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Singkatan dari quality assurance: semua yang dilakukan untuk memastikan pekerjaan benar sebelum tayang. Di AI-gile itu berarti pemeriksaan otomatis: kalau QA merah, ada yang gagal, dan tidak bisa tayang sampai diperbaiki.","also":["pemeriksaan kualitas","quality checks"]},{"id":"testpile","g":"test","word":"Tumpukan tes","text":"Kartu selesai yang menunggu kamu coba, satu per satu. Terima satu atau kembalikan dengan catatan, lalu kartu berikutnya muncul.","also":["test pile"]},{"id":"autotest","g":"test","word":"Tes otomatis","text":"Pemeriksaan yang dijalankan komputer sendiri setiap kali kode berubah, untuk menangkap kesalahan sejak dini.","also":["automated test","automated tests","automatic tests","tes otomatis"]},{"id":"manualtest","g":"test","word":"Tes manual","text":"Seseorang mencoba sendiri pekerjaan itu secara manual untuk melihat apakah sudah berjalan sebagaimana mestinya.","also":["manual test","manual tests","manual testing","tes manual"]},{"id":"unittest","g":"test","word":"Unit test","text":"Pemeriksaan otomatis kecil terhadap satu potongan kode yang sangat kecil secara terpisah.","also":["unit test","unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"Pemeriksaan bahwa beberapa bagian bekerja baik bersama-sama, bukan hanya satu per satu.","also":["integration test","integration tests","tes integrasi"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"Tes yang bertindak seperti pengguna sungguhan dari awal sampai akhir, misalnya mendaftar, membeli, dan membayar.","also":["E2E","end-to-end tests","tes menyeluruh"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"Orang yang meminta pekerjaan itu mencobanya sendiri dan menyatakan apakah sudah sesuai kebutuhan mereka. Tumpukan tes di AI-gile adalah versinya.","also":["UAT","acceptance testing","uji penerimaan"]},{"id":"regression","g":"test","word":"Regresi","text":"Sesuatu yang dulu berfungsi tetapi rusak setelah ada perubahan. Tes regresi memeriksa bahwa hal-hal lama masih berfungsi.","also":["regression","regressions","regression test","regression tests","regression testing","regresi"]},{"id":"smoke","g":"test","word":"Smoke test","text":"Pemeriksaan sangat cepat bahwa hal-hal utama berfungsi sama sekali, misalnya tepat setelah perubahan tayang. Kalau gagal, berhenti dan periksa.","also":["smoke test","smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Mencoba produk dengan bebas dan mengutak-atiknya dengan berbagai cara, untuk menemukan masalah yang terlewat oleh pemeriksaan terencana.","also":["exploratory testing","exploratory test","exploratory tests","uji eksploratif"]},{"id":"testcase","g":"test","word":"Test case","text":"Satu skenario tertulis untuk dicoba: langkah-langkahnya, dan apa yang seharusnya terjadi.","also":["test case","test cases","kasus uji"]},{"id":"coverage","g":"test","word":"Test coverage","text":"Seberapa banyak kode yang diperiksa oleh tes otomatis. Lebih banyak biasanya lebih aman, tetapi coverage tinggi saja tidak membuktikan semuanya berjalan baik.","also":["test coverage","code coverage","cakupan tes"]},{"id":"testdata","g":"test","word":"Data uji","text":"Informasi contoh rekaan yang dipakai saat menguji, sehingga data pribadi orang sungguhan tidak terbuka.","also":["test data","test fixtures","data uji"]},{"id":"edgecase","g":"test","word":"Edge case","text":"Situasi tak biasa di batas, seperti formulir kosong atau nama dengan apostrof, tempat sesuatu sering rusak.","also":["edge case","edge cases","kasus tepi"]},{"id":"happypath","g":"test","word":"Happy path","text":"Jalur normal saat semuanya berjalan lancar. Pengujian yang baik juga mencoba jalur yang tidak mulus."},{"id":"perftest","g":"test","word":"Uji performa","text":"Memeriksa seberapa cepat sesuatu dan seberapa baik ia bertahan di bawah tekanan.","also":["performance testing","performance test","performance tests","uji performa"]},{"id":"loadtest","g":"test","word":"Uji beban","text":"Memeriksa bagaimana sebuah sistem bertahan saat banyak orang memakainya sekaligus.","also":["load testing","load test","load tests","uji beban"]},{"id":"sectest","g":"test","word":"Uji keamanan","text":"Mencari kelemahan yang bisa membuat seseorang menyalahgunakan sistem atau melihat apa yang tidak seharusnya.","also":["security testing","security test","security tests","uji keamanan"]},{"id":"accesstest","g":"test","word":"Uji aksesibilitas","text":"Memeriksa bahwa orang dengan kemampuan berbeda bisa memakai produk, termasuk dengan pembaca layar atau hanya keyboard.","also":["accessibility testing","accessibility test","uji aksesibilitas"]},{"id":"linting","g":"test","word":"Linting","text":"Pemeriksaan otomatis yang menemukan kemungkinan kesalahan dan gaya yang berantakan di kode, seperti pemeriksa ejaan untuk program.","also":["linting","linter","lint"]},{"id":"static","g":"test","word":"Analisis statis","text":"Memeriksa masalah pada kode dengan membacanya secara otomatis, tanpa menjalankannya.","also":["static analysis","static code analysis","analisis statis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"Tes yang kadang lulus dan kadang gagal tanpa sebab jelas, sehingga tak bisa sepenuhnya dipercaya.","also":["flaky test","flaky tests","tes tak stabil"]},{"id":"repro","g":"test","word":"Mereproduksi (repro)","text":"Membuat bug terjadi lagi dengan sengaja lewat langkah yang sama, supaya bisa dipelajari dan diperbaiki. Menuliskan langkah-langkah itu adalah bagian paling berguna dari laporan bug.","also":["repro","reproduce","steps to reproduce","langkah reproduksi","mereproduksi"]},{"id":"severity","g":"test","word":"Tingkat keparahan","text":"Seberapa buruk dampak sebuah masalah, dari gangguan kecil sampai semuanya berhenti.","also":["severity","severity level","severitas"]},{"id":"deploy","g":"change","word":"Deploy","text":"Menyalin versi baru perangkat lunak ke komputer yang menjalankannya, seperti salinan uji atau layanan yang tayang."},{"id":"release","g":"change","word":"Rilis","text":"Sekumpulan pekerjaan selesai yang diberi nama dan live bersama-sama, dengan catatan singkat tentang apa yang berubah. 🚀 Rilis menulis catatannya dari kartu yang sudah selesai.","also":["release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Kembali ke versi terakhir yang berfungsi ketika versi baru menimbulkan masalah. Di AI-gile, Roll back mengumpulkan langkah pembatalan yang ditulis pada tiap perubahan menjadi satu daftar periksa.","also":["roll back","kembalikan versi"]},{"id":"live","g":"change","word":"Live","text":"Versi asli yang dipakai orang, bukan salinan untuk mencoba-coba. Developer juga menyebutnya production.","also":["production","produksi"],"noTip":1},{"id":"change","g":"change","word":"Perubahan","text":"Perubahan terencana pada sesuatu yang diandalkan orang, ditulis lebih dulu: apa, kenapa, risikonya, kapan, dan cara membatalkannya. Mulai dengan 🔀 Ajukan perubahan.","also":["permintaan perubahan","change request"],"noTip":1},{"id":"risk","g":"change","word":"Risiko","text":"Sesuatu yang bisa salah, diberi skor menurut seberapa mungkin terjadi dan seberapa parah akibatnya. ⚠️ Risiko menyimpannya dalam satu daftar, skor tertinggi di atas, masing-masing dengan tanggal untuk ditinjau lagi.","also":["daftar risiko","risk","risk register"]},{"id":"chgwin","g":"change","word":"Jendela perubahan","text":"Waktu ketika perubahan boleh live, misalnya Selasa malam yang sepi. Di luar jendela, kartu perubahan tidak bisa diselesaikan, kecuali darurat.","also":["change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Pemeriksaan terakhir tepat sebelum perubahan tayang: setiap orang yang harus menyetujui menyatakan Go atau No go. Baru berjalan kalau semua mengatakan Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Persetujuan","text":"Menunggu kata ya sebelum pekerjaan dimulai. Kartu yang diajukan teman, atau perubahan, menunggu di ✅ Persetujuan sampai kamu menyetujui atau menolaknya.","also":["approval"]},{"id":"quiettime","g":"change","word":"Waktu tenang","text":"Rentang waktu, seperti saat siaran langsung, demo, atau semalaman, ketika tidak ada yang tayang. Tim terus bekerja dan menguji, tetapi tayang menunggu sampai selesai. Di tempat lain disebut change freeze.","also":["change freeze","pembekuan perubahan"]},{"id":"devops","g":"change","word":"DevOps","text":"Cara kerja saat orang yang membuat perangkat lunak dan orang yang menjalankannya bekerja sebagai satu tim, dengan banyak otomatisasi, sehingga perubahan sering tayang dengan aman."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration dan delivery)","text":"Perubahan semua orang sering digabung ke versi utama dan diperiksa otomatis setiap kali (continuous integration), sehingga perangkat lunak selalu siap tayang dengan satu tombol (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"Satu langkah lebih jauh dari continuous delivery: setiap perubahan yang lulus pemeriksaan tayang sendiri, tanpa tombol yang perlu ditekan.","also":["continuous deployment","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Rangkaian langkah otomatis yang dilalui sebuah perubahan menuju tayang, seperti build, tes, lalu deploy.","also":["pipeline","pipelines"]},{"id":"environment","g":"change","word":"Lingkungan (environment)","text":"Satu salinan sistem yang terpisah untuk satu tujuan, misalnya satu untuk membangun, satu untuk menguji, dan satu yang tayang.","also":["environment","environments","lingkungan"],"noTip":1},{"id":"devenv","g":"change","word":"Lingkungan pengembangan","text":"Salinan tempat developer bekerja, sering di komputernya sendiri, tempat merusak sesuatu tidak merugikan siapa pun.","also":["development environment","dev environment","lingkungan dev"]},{"id":"testenv","g":"change","word":"Lingkungan uji","text":"Salinan sistem terpisah yang dipakai khusus untuk pengujian, sehingga layanan sungguhan tidak tersentuh.","also":["test environment","test environments","lingkungan tes"]},{"id":"staging","g":"change","word":"Staging","text":"Salinan terakhir yang disiapkan persis seperti yang tayang, untuk pemeriksaan akhir sebelum perubahan tayang.","also":["staging","staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"File atau paket yang dihasilkan sebuah build, siap disimpan, diperiksa, atau ditayangkan.","also":["build artifact","build artifacts","artefak build"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Perbaikan mendesak yang ditayangkan cepat di luar rencana biasa, karena ada hal penting yang rusak.","also":["hotfix","hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"Pembaruan kecil yang memperbaiki bug atau menutup celah keamanan. Memasang patch keamanan dengan cepat itu penting.","also":["patch","patches","security patch","security patches","tambalan"]},{"id":"version","g":"change","word":"Nomor versi","text":"Label seperti 2.4.1 yang menyatakan rilis mana yang kamu punya. Sering angka pertama berubah untuk perubahan besar dan angka terakhir untuk perbaikan kecil.","also":["version number","version numbers","semantic versioning","nomor versi"]},{"id":"relnotes","g":"change","word":"Catatan rilis","text":"Daftar singkat dan jelas tentang apa yang berubah dalam sebuah rilis, untuk orang yang memakainya, termasuk perbaikan dan batasan yang diketahui. Disebut juga changelog.","also":["changelog","change log","release notes","catatan perubahan"]},{"id":"flag","g":"change","word":"Feature flag","text":"Saklar hidup-mati untuk sebuah fitur, sehingga pekerjaan baru bisa tayang tersembunyi lalu dinyalakan (atau dimatikan lagi) tanpa rilis baru.","also":["feature flag","feature flags","feature toggle","feature toggles","saklar fitur"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Memperbaiki rilis yang buruk dengan cepat merilis versi baru yang sudah dikoreksi, bukan kembali ke yang lama.","also":["roll forward","rolling forward","rolled forward","maju terus"]},{"id":"canary","g":"change","word":"Canary release","text":"Menayangkan perubahan lebih dulu untuk kelompok kecil, dan untuk semua orang hanya setelah terlihat baik. Dinamai dari burung kenari yang dibawa penambang ke bawah tanah sebagai peringatan dini.","also":["canary release","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Menyimpan dua salinan sistem yang tayang dan memindahkan orang ke yang baru sekaligus, sehingga bisa langsung pindah kembali kalau ada masalah.","also":["blue-green","blue green deployment","blue-green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Menayangkan versi baru tanpa layanan pernah berhenti bagi penggunanya.","also":["zero downtime","zero-downtime","tanpa downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Membantu perubahan berhasil: menimbang risiko, mendapatkan persetujuan yang tepat, dan memilih waktu yang baik. Disebut juga manajemen perubahan.","also":["change management","manajemen perubahan","change enablement"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"Kelompok yang meninjau perubahan penting dan menyepakati apakah dan kapan perubahan itu boleh dilanjutkan.","also":["CAB","change advisory board"]},{"id":"stdchange","g":"change","word":"Standard change","text":"Perubahan berisiko rendah yang dilakukan dengan cara yang sama dan teruji setiap kali, sehingga disetujui di muka.","also":["standard change","standard changes","perubahan standar"]},{"id":"normchange","g":"change","word":"Normal change","text":"Perubahan yang perlu diperiksa dan disetujui sebelum dilanjutkan.","also":["normal change","normal changes","perubahan normal"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"Perubahan yang harus dilakukan segera untuk memperbaiki atau mencegah masalah serius, dengan persetujuan yang lebih cepat.","also":["emergency change","emergency changes","perubahan darurat"]},{"id":"automation","g":"change","word":"Otomatisasi","text":"Membuat komputer mengerjakan tugas berulang dengan sendirinya, sehingga lebih cepat dan selalu dilakukan dengan cara yang sama.","also":["automation","automated","otomasi"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruktur","text":"Mesin, jaringan, dan layanan tempat perangkat lunak berjalan.","also":["infrastructure","infra","infrastruktur"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Menuliskan server dan pengaturanmu dalam file yang disimpan bersama kode, sehingga bisa dibangun ulang persis sama setiap kali.","also":["IaC","infrastructure as code"]},{"id":"cloud","g":"change","word":"Cloud (komputasi awan)","text":"Menyewa komputer, penyimpanan, dan layanan dari penyedia besar lewat internet, bukan memiliki mesinnya sendiri.","also":["cloud","the cloud","cloud computing","komputasi awan"]},{"id":"provider","g":"change","word":"Penyedia cloud","text":"Perusahaan yang menyewakan komputasi lewat internet, seperti Amazon Web Services (AWS), Microsoft Azure, atau Google Cloud.","also":["cloud provider","cloud providers","penyedia cloud"]},{"id":"hosting","g":"change","word":"Hosting","text":"Tempat aplikasi atau situsmu berada dan berjalan agar orang bisa mengaksesnya, biasanya disewa dari sebuah perusahaan.","also":["hosting"]},{"id":"domain","g":"change","word":"Nama domain","text":"Alamat web yang diketik orang, seperti example.com. Disewa per tahun, jadi harus diperpanjang.","also":["domain name","domain names","domain","nama domain"]},{"id":"dns","g":"change","word":"DNS","text":"Singkatan dari domain name system: buku alamat internet, yang mengubah nama seperti example.com menjadi alamat komputer yang tepat.","also":["domain name system"]},{"id":"container","g":"change","word":"Kontainer","text":"Paket tertutup berisi aplikasi dan semua yang dibutuhkannya, sehingga berjalan sama di komputer mana pun. Docker adalah alat yang paling dikenal.","also":["container","containers","Docker","kontainer"],"noTip":1},{"id":"vm","g":"change","word":"Mesin virtual (VM)","text":"Komputer pura-pura yang berjalan di dalam komputer sungguhan, sehingga satu mesin besar bisa bertindak sebagai banyak mesin.","also":["VM","VMs","virtual machines","mesin virtual"]},{"id":"serverless","g":"change","word":"Serverless","text":"Menjalankan kode tanpa mengurus server sendiri: penyedia menjalankannya saat dibutuhkan dan kamu membayar sesuai pemakaian."},{"id":"lb","g":"change","word":"Load balancer","text":"Sesuatu yang membagi pengunjung ke beberapa server, sehingga tak ada satu server pun yang kewalahan.","also":["load balancer","load balancers","penyeimbang beban"]},{"id":"cache","g":"change","word":"Cache","text":"Simpanan praktis berisi hasil terbaru yang ditaruh di tempat yang dekat, sehingga hal yang sama tak perlu diambil atau dihitung lagi. Mengosongkannya bisa memperbaiki halaman yang tampak usang.","also":["cache","caches","caching","cached","tembolok"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"Jaringan server di seluruh dunia yang menyimpan salinan halaman dan gambarmu di dekat pengunjung, sehingga cepat dimuat.","also":["CDN"]},{"id":"migration","g":"change","word":"Migrasi","text":"Memindahkan data atau sistem dari susunan lama ke yang baru, atau mengubah tata letak basis data dengan hati-hati.","also":["migration","migrations","database migration","migrasi"]},{"id":"service","g":"run","word":"Layanan","text":"Sesuatu yang kamu bangun dan diandalkan orang, seperti situs web atau aplikasi, yang dirawat supaya tetap berjalan. Centang “Proyek ini adalah layanan” lalu tulis apa yang ditawarkan, siapa yang memakainya, dan siapa yang siaga.","also":["service","servis"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"Berapa banyak waktu sebuah layanan berfungsi, biasanya dalam persen. 99,9% tetap membolehkan sekitar 43 menit mati sebulan.","also":["uptime","uptime percentage","persentase uptime"]},{"id":"uptime","g":"run","word":"Cek uptime","text":"Pemeriksaan otomatis, tiap beberapa menit, bahwa layananmu masih merespons. Kalau gagal beberapa kali berturut-turut, AI-gile membuka kartu insiden sendiri.","also":["pemeriksaan uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Halaman status","text":"Halaman publik yang menunjukkan apakah layanan berjalan (hijau, oranye atau merah) beserta kabar terbarunya, jadi orang yang memakainya bisa mengecek sendiri tanpa harus bertanya.","also":["status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Tempat masuknya pertanyaan dan laporan dari orang-orang yang memakai layananmu. AI-gile memilah masing-masing menjadi permintaan, insiden, atau ide, dan memberi tahu kalau sepertinya sudah pernah dilaporkan.","also":["meja layanan","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Permintaan layanan","text":"Seseorang meminta hal yang biasa, seperti akun baru atau sedikit bantuan, bukan melaporkan ada yang rusak. Permintaan menunggu gilirannya; insiden didahulukan.","also":["permintaan-permintaan layanan"]},{"id":"incident","g":"run","word":"Insiden","text":"Sesuatu yang rusak atau tidak berfungsi dengan benar bagi orang yang memakainya saat ini, seperti situs web mati atau sangat lambat. Kartu insiden 🔥 menyalip antrean: membuatnya berfungsi lagi didahulukan.","also":["incident"]},{"id":"major","g":"run","word":"Insiden besar","text":"Insiden yang parah: banyak orang terdampak, atau uang atau data dalam bahaya. Satu tombol mengerahkan semua tim (swarm), membangunkan siapa pun yang siaga, dan meminta kabar status tiap 30 menit.","also":["major incident"]},{"id":"oncall","g":"run","word":"Siaga","text":"Menjadi orang yang menanggapi saat ada yang rusak, bahkan di malam hari. Setiap layanan punya anggota tim yang siaga dan dibangunkan pertama untuk insidennya.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Batas waktu balasan","text":"Berapa lama kartu boleh menunggu balasan pertama, misalnya satu jam untuk insiden. Setelah itu muncul jam merah, supaya tidak ada yang diam-diam terlupakan. Disebut juga target respons.","also":["target respons","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Tinjauan singkat setelah insiden: apa yang terjadi, apa yang membantu, dan apa yang perlu diubah, tanpa menyalahkan siapa pun. Insiden tidak bisa ditutup tanpanya.","also":["postmortem","post-incident review","tinjauan pasca-insiden"]},{"id":"problem","g":"run","word":"Masalah","text":"Penyebab tersembunyi di balik satu insiden atau lebih. Kartu 🧩 masalah mengumpulkan insiden yang terus kembali, supaya penyebabnya ditemukan dan diperbaiki untuk selamanya.","also":["problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Akar masalah","text":"Alasan sebenarnya kenapa sesuatu rusak, bukan sekadar apa yang kamu lihat salah. Perbaiki akar masalahnya dan insiden berhenti kembali.","also":["root cause","akar penyebab"]},{"id":"workaround","g":"run","word":"Solusi sementara","text":"Cara menjaga semuanya tetap berjalan sampai perbaikan sebenarnya siap, misalnya me-restart sesuatu saat macet. Ditulis di kartu masalah supaya tidak ada yang perlu mencarinya lagi.","also":["workaround"]},{"id":"knownerror","g":"run","word":"Kesalahan yang diketahui","text":"Masalah yang penyebabnya sudah dipahami tetapi belum diperbaiki, biasanya dengan solusi sementara yang dicatat. 🧩 Kesalahan yang diketahui mendaftarkannya, supaya semua orang memakai solusi itu dan tidak menggali ulang.","also":["known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Petunjuk langkah demi langkah untuk memperbaiki jenis gangguan yang sudah dikenal, supaya dikerjakan dengan cara yang sama, cepat, setiap kali. Setelah insiden besar, tim bisa mengusulkan satu untuk kamu OK-kan.","also":["runbooks"]},{"id":"ci","g":"run","word":"Item konfigurasi","text":"Satu hal yang diandalkan layananmu, seperti server, domain, sertifikat, kunci, atau pemasok. 🗂️ Item konfigurasi mendaftarnya per layanan, supaya kamu bisa melihat apa yang terdampak insiden dan apa yang perlu diperbarui atau dicadangkan.","also":["item-item konfigurasi","configuration item"]},{"id":"expiry","g":"run","word":"Tanggal kedaluwarsa","text":"Tanggal ketika sesuatu berhenti berfungsi kecuali diperpanjang, seperti sertifikat keamanan situs web atau alamat webnya. AI-gile memantau tanggal-tanggal ini dan membuat satu kartu untuk memperpanjang tiap-tiapnya 30 hari sebelumnya, supaya tidak ada yang berhenti mendadak.","also":["tanggal-tanggal kedaluwarsa","kedaluwarsa","pantauan kedaluwarsa"]},{"id":"backup","g":"run","word":"Cadangan","text":"Salinan datamu yang disimpan dari sebelumnya, untuk diandalkan kalau ada yang hilang atau rusak. AI-gile membuat cadangan papan-papanmu setiap hari.","also":["backup","backups"]},{"id":"restore","g":"run","word":"Pulihkan","text":"Mengembalikan data dari cadangan. Cadangan baru benar-benar berarti kalau kamu tahu itu bisa dipulihkan, jadi sesekali patut dicoba.","also":["memulihkan","dipulihkan","restore"]},{"id":"svcreview","g":"run","word":"Tinjauan layanan","text":"Melihat kembali satu bulan sebuah layanan: insiden yang dibuka dan diperbaiki, seberapa cepat orang mendapat jawaban, uptime, dan token yang terpakai. Tinjauan bulanan menampilkannya untuk tiap layanan.","also":["tinjauan-tinjauan layanan","tinjauan bulanan"]},{"id":"accessreview","g":"run","word":"Tinjauan akses","text":"Memeriksa setiap 90 hari siapa yang masih bisa masuk: tautan berbagi, peran teman, serta kata sandi dan kunci yang tersimpan. Kamu mempertahankan atau menghapus masing-masing, supaya akses lama tidak menggantung.","also":["tinjauan-tinjauan akses"]},{"id":"improvements","g":"run","word":"Daftar perbaikan","text":"Semua hal yang diputuskan tim untuk diperbaiki, di satu tempat: saran retro, tindakan tinjauan, dan perbaikan masalah, masing-masing dengan statusnya. Ada di bawah 📈 Perbaikan.","also":["daftar-daftar perbaikan","perbaikan"]},{"id":"tokencap","g":"run","word":"Batas token","text":"Batas bulanan untuk token yang boleh dipakai agen-agen sebuah layanan. Di 80% kamu mendapat peringatan; di 100% pekerjaan latar mereka menunggu sampai bulan depan atau sampai kamu menaikkan batasnya.","also":["batas-batas token","token cap"]},{"id":"svcmgmt","g":"run","word":"Manajemen layanan","text":"Semua yang terlibat dalam menjaga sebuah layanan tetap berguna dan berfungsi bagi orang yang mengandalkannya, hari demi hari.","also":["service management","manajemen layanan"]},{"id":"itil","g":"run","word":"ITIL","text":"Panduan yang banyak dipakai untuk manajemen layanan yang baik, mencakup hal seperti insiden, masalah, dan perubahan. Namanya dulu singkatan dari IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Menjalankan teknologi sebagai layanan bagi orang, dengan cara jelas untuk menangani permintaan, insiden, perubahan, dan perbaikan.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"Layanan yang dijalankan dan dirawat orang lain untukmu, berdasarkan perjanjian tentang seberapa baik layanan itu harus berfungsi.","also":["managed service","managed services","layanan terkelola"]},{"id":"svcowner","g":"run","word":"Pemilik layanan","text":"Orang yang bertanggung jawab atas sebuah layanan secara keseluruhan: seberapa baik berfungsi, berapa biayanya, dan bagaimana ia membaik.","also":["service owner","service owners","pemilik layanan"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"Janji tertulis kepada pelanggan tentang seberapa baik layanan akan berfungsi, seperti “aktif 99,9% waktu” atau “dijawab dalam satu jam”, sering dengan uang kembali jika dilanggar.","also":["SLA","SLAs","service level agreement","perjanjian tingkat layanan"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"Target internal tim tentang seberapa baik layanan harus berfungsi dalam suatu periode, biasanya ditetapkan sedikit lebih ketat dari SLA agar aman.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"Pengukuran sebenarnya yang kamu bandingkan dengan target, seperti persentase kunjungan yang dimuat dengan baik.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Ketersediaan","text":"Apakah orang bisa memakai layanan saat mereka membutuhkannya, sering diukur sebagai uptime.","also":["availability","high availability","ketersediaan tinggi"]},{"id":"downtime","g":"run","word":"Downtime","text":"Waktu ketika layanan tidak berfungsi atau dimatikan, terencana maupun tidak.","also":["downtime","down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"Sedikit kegagalan yang dibolehkan target keandalanmu. Selama masih ada sisa, kamu boleh mengambil risiko dengan perubahan; setelah habis, kamu harus memperlambat langkah.","also":["error budget","error budgets","anggaran kesalahan"]},{"id":"outage","g":"run","word":"Outage","text":"Saat layanan mati atau rusak parah bagi penggunanya.","also":["outage","outages","gangguan layanan"]},{"id":"degraded","g":"run","word":"Degraded","text":"Masih berfungsi, tetapi buruk: lambat, atau ada bagian yang tidak berfungsi.","also":["degraded","degraded service","layanan menurun"]},{"id":"monitoring","g":"run","word":"Pemantauan (monitoring)","text":"Mengawasi layanan secara otomatis sepanjang waktu, sehingga masalah ketahuan, idealnya sebelum pengguna menyadarinya.","also":["monitoring","pemantauan"]},{"id":"observability","g":"run","word":"Observability","text":"Seberapa baik kamu bisa mengetahui apa yang terjadi di dalam sebuah sistem dari luar, lewat log, angka, dan trace-nya.","also":["o11y","observability","observabilitas"]},{"id":"log","g":"run","word":"Log","text":"Catatan harian yang terus ditulis sebuah program tentang apa yang dikerjakannya, dipakai untuk menelusuri apa yang salah.","also":["log","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"Catatan perjalanan satu permintaan melewati berbagai bagian sistem, langkah demi langkah, yang menunjukkan di mana ia melambat.","also":["trace","traces","tracing","jejak"]},{"id":"latency","g":"run","word":"Latensi","text":"Berapa lama sesuatu menjawab, seperti jeda antara mengeklik dan halaman muncul.","also":["latency","latensi"]},{"id":"alert","g":"run","word":"Peringatan (alert)","text":"Pesan otomatis bahwa ada yang perlu diperhatikan, seperti situs web yang tidak menjawab.","also":["alert","alerts","alerting","peringatan"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Kelelahan alert","text":"Ketika alert begitu banyak sampai orang mulai mengabaikannya, termasuk yang penting.","also":["alert fatigue","alarm fatigue","kelelahan alert"]},{"id":"dashboard","g":"run","word":"Dasbor","text":"Layar yang menampilkan angka dan status terpenting sekilas.","also":["dashboard","dashboards","dasbor"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Menelepon atau membangunkan petugas jaga dengan mendesak tentang suatu masalah.","also":["paging","paged"]},{"id":"escalation","g":"run","word":"Eskalasi","text":"Melibatkan orang yang lebih ahli atau berwenang ketika masalah tak bisa diselesaikan di tingkat sekarang, atau tak cukup cepat.","also":["escalation","escalate","escalated","eskalasi"]},{"id":"triage","g":"run","word":"Triase","text":"Memilah laporan masuk dengan cepat menurut seberapa mendesak dan penting, supaya yang terburuk ditangani lebih dulu.","also":["triage","triaged","triase"]},{"id":"impact","g":"run","word":"Dampak","text":"Seberapa besar sesuatu memengaruhi orang: berapa banyak, dan seberapa parah.","noTip":1},{"id":"urgency","g":"run","word":"Urgensi","text":"Seberapa cepat sesuatu perlu ditangani. Dampak dan urgensi bersama-sama menentukan prioritas.","noTip":1},{"id":"plevels","g":"run","word":"Level prioritas (P1, P2…)","text":"Label untuk seberapa mendesak sebuah masalah. P1 paling serius dan perlu ditindak segera.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Antrean tiket","text":"Daftar permintaan dan insiden yang menunggu untuk diambil.","also":["ticket queue","ticket queues","antrean tiket"]},{"id":"tiers","g":"run","word":"Lini pertama dan lini kedua","text":"Tingkat dukungan: lini pertama menerima panggilan dan memperbaiki hal sederhana; lini kedua punya keahlian lebih dalam untuk yang lebih sulit. Disebut juga tier 1 dan tier 2.","also":["first-line support","tier 1","tier 2","lini pertama","lini kedua"]},{"id":"ic","g":"run","word":"Incident commander","text":"Satu orang yang memimpin penanganan sebuah insiden, sehingga semua orang tahu siapa yang memutuskan dan siapa mengerjakan apa.","also":["incident commander","incident commanders","komandan insiden"]},{"id":"responsetime","g":"run","word":"Waktu respons","text":"Berapa lama sampai seseorang pertama kali mengambil sebuah permintaan atau insiden.","also":["response time","response times","waktu respons"]},{"id":"resolution","g":"run","word":"Waktu penyelesaian","text":"Berapa lama untuk menyelesaikan sepenuhnya sebuah permintaan atau insiden, dari dilaporkan sampai diperbaiki.","also":["resolution time","resolution times","time to resolve","waktu penyelesaian"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"Rata-rata berapa lama untuk membuat layanan berfungsi lagi setelah rusak. MTTR bisa berarti sedikit berbeda, jadi sebutkan apa yang kamu ukur.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"Rata-rata berapa lama sebuah layanan berjalan sebelum ada yang rusak.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"Daftar semua item konfigurasimu dan cara mereka terhubung, sehingga kamu bisa melihat apa bergantung pada apa.","also":["CMDB"]},{"id":"asset","g":"run","word":"Aset","text":"Apa pun yang bernilai yang kamu miliki atau bayar untuk menjalankan layanan, seperti laptop, lisensi perangkat lunak, atau domain.","also":["asset","assets","aset"],"noTip":1},{"id":"capplan","g":"run","word":"Perencanaan kapasitas","text":"Memastikan akan ada cukup daya komputer, penyimpanan, dan orang untuk apa yang akan datang.","also":["capacity planning","capacity plan","perencanaan kapasitas"]},{"id":"scaling","g":"run","word":"Scaling","text":"Menangani lebih banyak pengguna dengan memberi satu mesin lebih banyak daya (scaling up) atau menambah lebih banyak mesin (scaling out).","also":["scale up","scale out","scaling up","scaling out","scaling"]},{"id":"bcp","g":"run","word":"Kelangsungan bisnis","text":"Rencana untuk menjaga hal-hal penting tetap berjalan ketika sesuatu yang besar salah, seperti kehilangan kantor, pemasok utama, atau komputer.","also":["business continuity plan","business continuity","kelangsungan bisnis"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"Rencana dan alat untuk mengembalikan layanan setelah kejadian serius, seperti kehilangan seluruh pusat data.","also":["disaster recovery","pemulihan bencana"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"Waktu terlama sebuah layanan boleh mati setelah bencana sebelum harus berfungsi lagi.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"Seberapa banyak data terbaru yang sanggup kamu relakan hilang, diukur dalam waktu. RPO satu jam berarti cadangan setidaknya tiap jam.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundansi","text":"Menyiapkan cadangan, seperti server kedua, sehingga satu kegagalan tidak menghentikan layanan.","also":["redundancy","redundansi"]},{"id":"failover","g":"run","word":"Failover","text":"Beralih sendiri ke sistem cadangan ketika yang biasa gagal.","also":["failover","fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"Satu bagian yang membuat semuanya ikut mati saat rusak, karena tidak ada cadangannya.","also":["single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Jendela pemeliharaan","text":"Waktu terencana saat layanan boleh dijeda atau melambat untuk perawatan, diumumkan kepada pengguna sebelumnya.","also":["maintenance window","maintenance windows","planned maintenance","jendela pemeliharaan"]},{"id":"handover","g":"run","word":"Serah terima","text":"Menyerahkan pekerjaan, pengetahuan, dan tanggung jawab kepada orang atau tim lain, supaya tidak ada yang terlewat.","also":["handover","handovers","serah terima"]},{"id":"kb","g":"run","word":"Knowledge base","text":"Kumpulan artikel bantuan dan jawaban, untuk pengguna maupun tim.","also":["knowledge base","knowledge bases","basis pengetahuan"]},{"id":"csat","g":"run","word":"Kepuasan pelanggan (CSAT)","text":"Skor dari pengguna yang menyatakan seberapa puas mereka, sering ditanyakan setelah sebuah permintaan ditutup.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Pemasok","text":"Perusahaan luar yang kamu andalkan, seperti penyedia hosting-mu. Disebut juga vendor atau pihak ketiga.","also":["supplier","suppliers","vendor","vendors","third party","pemasok","pihak ketiga"],"noTip":1},{"id":"retire","g":"run","word":"Penghentian layanan","text":"Mematikan sebuah layanan untuk selamanya dengan aman: memberi tahu penggunanya, mengurus data dan aksesnya, dan menghentikan biayanya.","also":["service retirement","retiring a service","penghentian layanan"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"Saat sebuah produk tak lagi mendapat pembaruan atau dukungan dari pembuatnya, sehingga harus diganti.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Keamanan siber","text":"Melindungi sistem dan data dari pembobolan, pencurian, atau kerusakan.","also":["cybersecurity","cyber security","keamanan siber"]},{"id":"authn","g":"sec","word":"Autentikasi","text":"Memeriksa siapa seseorang, biasanya dengan kata sandi atau kode. Sering disingkat authn.","also":["authn","authentication","autentikasi"]},{"id":"authz","g":"sec","word":"Otorisasi","text":"Memeriksa apa yang boleh dilakukan seseorang setelah kamu tahu siapa dia. Sering disingkat authz.","also":["authz","authorization","authorisation","otorisasi"]},{"id":"mfa","g":"sec","word":"Autentikasi multifaktor (MFA)","text":"Masuk dengan dua bukti atau lebih, seperti kata sandi ditambah kode di ponselmu. Disebut juga dua faktor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","autentikasi dua faktor"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Masuk sekali untuk mengakses banyak sistem, seperti memakai akun kerjamu di mana-mana.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Pengelola kata sandi","text":"Aplikasi yang membuat kata sandi yang kuat dan mengingatnya untukmu.","also":["password manager","password managers","pengelola kata sandi"]},{"id":"secret","g":"sec","word":"Secret (rahasia)","text":"Kata sandi, kunci, atau kode pribadi lain yang dipakai program untuk masuk ke sesuatu. Tidak boleh dibagikan atau ditulis di dalam kode.","also":["secret","secrets","rahasia"],"noTip":1},{"id":"apikey","g":"sec","word":"Kunci API","text":"Kode rahasia yang memungkinkan program memakai API layanan lain, dan menunjukkan siapa yang memakai (dan membayarnya).","also":["API key","API keys","kunci API"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"Tiket sementara yang membuktikan sebuah program boleh masuk, sehingga tak perlu kata sandimu setiap kali. Tidak sama dengan token AI.","also":["access token","access tokens","token akses"]},{"id":"encryption","g":"sec","word":"Enkripsi","text":"Mengacak informasi sehingga hanya orang dengan kunci yang tepat yang bisa membacanya.","also":["encryption","encrypted","encrypt","enkripsi"]},{"id":"https","g":"sec","word":"HTTPS","text":"Cara aman halaman web berpindah, ditandai gembok di peramban, sehingga tak ada yang di tengah bisa membaca atau mengubahnya."},{"id":"cert","g":"sec","word":"Sertifikat SSL/TLS","text":"Kartu identitas digital yang memungkinkan situs web membuktikan siapa dirinya dan memakai HTTPS. Ada masa berlakunya, jadi harus diperpanjang.","also":["TLS certificate","SSL certificate","certificate","certificates","sertifikat"]},{"id":"permissions","g":"sec","word":"Izin akses","text":"Aturan tentang siapa yang boleh melihat atau mengubah apa.","also":["permissions","permission","izin"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Memberi setiap orang atau program hanya akses yang benar-benar dibutuhkan, dan hanya selama dibutuhkan.","also":["principle of least privilege","hak akses minimum"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Memberi akses berdasarkan peran, seperti pelihat atau penyunting, bukan orang per orang.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Kerentanan","text":"Kelemahan yang bisa dimanfaatkan seseorang untuk membobol atau menimbulkan kerugian.","also":["vulnerability","vulnerabilities","kerentanan"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Kelemahan yang diketahui penyerang sebelum pembuatnya sempat memperbaikinya.","also":["zero-day","zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Perangkat lunak berbahaya, seperti virus, yang dibuat untuk merusak, memata-matai, atau mencuri.","also":["malware"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware yang mengunci file-mu dan meminta uang untuk membukanya. Cadangan yang baik adalah pertahanan terbaik.","also":["ransomware attack","serangan ransomware"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Pesan palsu yang berusaha menipumu agar menyerahkan kata sandi atau uang, atau membuka sesuatu yang berbahaya.","also":["phishing email","phishing emails","email phishing"]},{"id":"socialeng","g":"sec","word":"Rekayasa sosial","text":"Menipu manusia, bukan komputer, agar memberi akses, seperti telepon palsu dari “dukungan IT”."},{"id":"firewall","g":"sec","word":"Firewall","text":"Penjaga yang menentukan lalu lintas jaringan mana yang boleh masuk atau keluar.","also":["firewall","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Singkatan dari virtual private network: sambungan pribadi yang diacak lewat internet, sering dipakai untuk menjangkau sistem kerja dengan aman.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Membanjiri layanan dengan begitu banyak lalu lintas palsu sampai orang sungguhan tak bisa memakainya. DDoS berarti serangannya datang dari banyak komputer sekaligus.","also":["DoS","DDoS","denial of service","DDoS attack","serangan DDoS"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Menyewa pakar yang bersahabat untuk mencoba membobol, supaya kelemahan ditemukan sebelum penyerang sungguhan menemukannya.","also":["pen test","pen testing","penetration testing","pentest","uji penetrasi"]},{"id":"audit","g":"sec","word":"Audit keamanan","text":"Pemeriksaan cermat tentang seberapa baik sesuatu dilindungi, dibandingkan dengan daftar praktik yang baik.","also":["security audit","security audits","audit keamanan"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Memikirkan siapa yang mungkin menyerang sesuatu, bagaimana caranya, dan apa yang akan kamu lakukan untuk menghentikan mereka.","also":["threat model","threat modeling","pemodelan ancaman"]},{"id":"breach","g":"sec","word":"Kebocoran data","text":"Ketika informasi pribadi sampai ke orang yang tidak seharusnya memilikinya, atau hilang atau diubah tanpa izin.","also":["data breach","data breaches","kebocoran data"]},{"id":"pii","g":"sec","word":"Data pribadi","text":"Informasi apa pun tentang orang yang bisa dikenali, seperti nama, alamat email, atau lokasi. Disebut juga PII.","also":["PII","personally identifiable information","personal data","data pribadi"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Hukum Eropa tentang data pribadi (Inggris punya versinya sendiri): kumpulkan hanya yang kamu butuhkan, jaga keamanannya, dan biarkan orang melihat atau menghapus datanya.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Pelindungan data","text":"Menjaga data pribadi dengan benar dan sesuai hukum.","also":["data protection","data protection law","perlindungan data"]},{"id":"privacypolicy","g":"sec","word":"Kebijakan privasi","text":"Halaman publik yang menyatakan data pribadi apa yang kamu kumpulkan, mengapa, dan apa yang kamu lakukan dengannya.","also":["privacy policy","privacy statement","privacy notice","kebijakan privasi"]},{"id":"consent","g":"sec","word":"Persetujuan","text":"“Ya” yang jelas dan bebas dari seseorang agar datanya dipakai dengan cara tertentu. Mereka bisa menariknya kapan saja.","also":["consent","opt-in","persetujuan"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"File kecil yang disimpan situs web di peramban untuk mengingat sesuatu, seperti status masuk. Sebagian perlu persetujuanmu lebih dulu.","also":["cookie","cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Minimalisasi data","text":"Mengumpulkan dan menyimpan hanya data pribadi yang benar-benar dibutuhkan untuk tugasnya.","also":["data minimisation","data minimization","minimalisasi data"]},{"id":"retention","g":"sec","word":"Retensi data","text":"Berapa lama data disimpan sebelum dihapus. Menyimpannya tidak lebih lama dari perlu lebih aman dan sering diwajibkan hukum.","also":["data retention","retention period","masa retensi"]},{"id":"anon","g":"sec","word":"Anonimisasi","text":"Mengubah data sehingga tak seorang pun dapat dikenali lagi darinya secara wajar.","also":["anonymisation","anonymised","anonymization","anonymous data","anonimisasi"]},{"id":"pseudo","g":"sec","word":"Pseudonimisasi","text":"Mengganti nama dan detail lain dengan kode, dengan kunci yang disimpan terpisah untuk menghubungkannya kembali. Ini tetap data pribadi.","also":["pseudonymisation","pseudonymised","pseudonymization","pseudonimisasi"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"Kontrak yang menyatakan bagaimana pemasok boleh menangani data pribadi atas namamu.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"Telaah cermat sebelum mulai tentang bagaimana rencana memakai data pribadi bisa memengaruhi orang dan bagaimana menurunkan risikonya.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Log audit","text":"Catatan tentang siapa melakukan apa dan kapan, sehingga tindakan bisa diperiksa nanti.","also":["audit log","audit logs","audit trail","log audit"]},{"id":"compliance","g":"sec","word":"Kepatuhan (compliance)","text":"Mengikuti hukum, aturan, dan standar yang berlaku bagimu, dan mampu menunjukkan bahwa kamu melakukannya.","also":["compliance","compliant","kepatuhan"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Standar internasional yang terkenal untuk mengelola keamanan informasi. Perusahaan bisa disertifikasi berdasarkan standar ini.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Laporan dari AS, diperiksa auditor luar, yang menunjukkan sebuah perusahaan menjaga data pelanggan dengan baik.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agen","text":"AI yang mengerjakan tugas sendiri: membaca kode, membuat perubahan, menjalankan pemeriksaan, dan melapor kembali. Hasil kerjanya tetap diperiksa.","also":["agen","agent"]},{"id":"token","g":"ai","word":"Token","text":"Potongan teks kecil yang dibaca dan ditulis AI, sekitar tiga perempat kata per token. Pemakaian AI dihitung dalam token, jadi makin sedikit token makin banyak sisa paketmu.","also":["token","tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Perintah kecil yang berjalan sendiri pada saat tertentu, misalnya saat sesi AI dimulai, supaya tim mendengar komentarmu.","also":["hook","hooks"]},{"id":"ai","g":"ai","word":"Kecerdasan buatan (AI)","text":"Sistem komputer yang melakukan hal-hal yang biasanya kita anggap butuh manusia, seperti menulis, menjawab pertanyaan, atau mengenali gambar.","also":["AI","artificial intelligence","kecerdasan buatan"],"noTip":1},{"id":"ml","g":"ai","word":"Pembelajaran mesin (ML)","text":"Cara membuat komputer mempelajari pola dari banyak contoh, bukan diberi aturan yang pasti.","also":["ML","machine learning","pembelajaran mesin"]},{"id":"model","g":"ai","word":"Model","text":"“Otak” terlatih dari sebuah sistem AI, yang dibangun dengan belajar dari contoh dalam jumlah sangat besar. Model berbeda dalam kemampuan, kecepatan, dan harga.","also":["model","models","AI model","model AI"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"Model AI yang dilatih dengan teks dalam jumlah sangat besar, sehingga bisa membaca dan menulis bahasa.","also":["LLM","LLMs","model bahasa besar"]},{"id":"genai","g":"ai","word":"AI generatif","text":"AI yang membuat hal baru, seperti teks, gambar, atau kode, bukan hanya memilah atau mengenalinya.","also":["GenAI","Generative AI","AI generatif"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Program yang bisa kamu ajak bicara dengan bahasa sehari-hari, dengan mengetik atau berbicara.","also":["chatbot","chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Apa yang kamu berikan kepada AI: pertanyaan atau instruksimu, ditambah apa pun yang kamu serahkan. Prompt yang lebih jelas biasanya mendapat jawaban yang lebih baik.","also":["prompt","prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"Keterampilan menulis prompt yang memberi jawaban yang andal dan berguna.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Instruksi latar yang diterima AI sebelum percakapan dimulai, yang menetapkan peran dan aturannya. Bobotnya lebih besar daripada yang kamu ketik.","also":["system prompt","system prompts","system instruction","system instructions","instruksi sistem"]},{"id":"context","g":"ai","word":"Konteks","text":"Semua yang bisa dilihat AI saat bekerja: instruksi, pesanmu, file yang sudah dibacanya, dan jawaban sebelumnya.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"Seberapa banyak yang bisa diingat AI sekaligus, diukur dalam token. Lewat dari itu, bagian yang lebih lama dibuang atau diringkas.","also":["context window","context windows","jendela konteks"]},{"id":"session","g":"ai","word":"Sesi","text":"Satu percakapan kerja dengan AI, dari awal sampai akhir. Sesi baru dimulai dengan ingatan yang segar.","also":["session","sessions","sesi"],"noTip":1},{"id":"memory","g":"ai","word":"Memori","text":"Catatan yang disimpan AI di antara sesi, sehingga ia ingat preferensimu dan keputusan sebelumnya.","noTip":1},{"id":"hallucination","g":"ai","word":"Halusinasi","text":"Ketika AI mengatakan sesuatu yang terdengar yakin tetapi dikarang atau salah. Periksa fakta yang penting.","also":["hallucination","hallucinations","hallucinate","hallucinates","halusinasi"]},{"id":"training","g":"ai","word":"Pelatihan","text":"Mengajari sebuah model dengan memperlihatkan contoh dalam jumlah sangat besar, sebelum ada yang memakainya.","also":["training","trained","pelatihan"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Data pelatihan","text":"Contoh-contoh tempat sebuah model belajar. Pengetahuannya berhenti pada tanggal data itu dikumpulkan.","also":["training data","training set","data latih"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"Tanggal berakhirnya pengetahuan bawaan AI. Ia tak akan tahu hal-hal sesudahnya kecuali mencarinya.","also":["knowledge cutoff","training cutoff","batas pengetahuan"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Pelatihan tambahan pada model yang sudah ada dengan contohmu sendiri, supaya lebih mahir pada satu pekerjaan tertentu.","also":["fine-tune","fine-tuned","fine tuning","fine-tuning"]},{"id":"inference","g":"ai","word":"Inferensi","text":"Model AI yang benar-benar dipakai untuk menjawab sesuatu, bukan sedang dilatih.","also":["inference","model inference","inferensi"]},{"id":"tooluse","g":"ai","word":"Penggunaan alat (tool use)","text":"AI yang bisa melakukan sesuatu, bukan hanya berbicara: menjalankan perintah, membaca file, atau mencari di web, lewat alat yang diberikan aplikasi.","also":["tool use","tool calling","tool call","tool calls","penggunaan alat"]},{"id":"subagent","g":"ai","word":"Subagen","text":"AI pembantu yang diberi tugas lebih kecil oleh AI utama, dan hasilnya dikembalikan kepadanya.","also":["subagent","subagents","sub-agent","subagen"]},{"id":"multiagent","g":"ai","word":"Multi-agen","text":"Beberapa AI bekerja bersama pada satu pekerjaan, masing-masing dengan bagiannya, seperti tim kecil.","also":["multi-agent","multi-agent system","sistem multi-agen"]},{"id":"autonomy","g":"ai","word":"Otonomi","text":"Seberapa banyak yang boleh dilakukan AI sendiri sebelum harus bertanya kepada manusia.","also":["autonomy","autonomous","otonom"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Melibatkan manusia untuk memeriksa atau menyetujui apa yang dilakukan AI pada titik-titik penting. Di AI-gile itu kamu.","also":["human-in-the-loop","HITL","human in the loop","manusia dalam proses"]},{"id":"guardrails","g":"ai","word":"Guardrail (pagar pengaman)","text":"Batasan dan pemeriksaan yang menjaga tindakan AI tetap aman, seperti perlunya persetujuan sebelum apa pun tayang. Ini menurunkan risiko kesalahan, tetapi tidak menghilangkannya.","also":["guardrail","guardrails","pagar pengaman"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Membiarkan AI mencari di dokumenmu sendiri sebelum menjawab, sehingga jawabannya bertumpu pada fakta milikmu.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Mengubah teks menjadi daftar angka yang menangkap maknanya, sehingga komputer bisa menemukan hal-hal yang bermakna mirip.","also":["embedding","embeddings"]},{"id":"vectordb","g":"ai","word":"Basis data vektor","text":"Basis data yang dibuat untuk mencari daftar angka itu (embedding), guna menemukan bahan dengan makna mirip.","also":["vector database","vector databases","vector store","basis data vektor"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Cara umum untuk menyambungkan alat dan sumber data ke aplikasi AI, sehingga AI bisa memakainya.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"Pengaturan seberapa berani jawaban AI. Rendah memberi jawaban yang lebih stabil dan terduga; tinggi memberi lebih beragam. Keduanya tidak membuatnya selalu benar.","also":["temperature","model temperature","suhu model"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Mampu bekerja dengan lebih dari satu jenis informasi, seperti teks, gambar, dan suara.","also":["multimodal","multi-modal"]},{"id":"evals","g":"ai","word":"Evaluasi (eval)","text":"Tes terencana tentang seberapa baik AI mengerjakan contoh yang dipilih, sehingga kamu bisa membandingkan model atau prompt.","also":["eval","evals","evaluasi"]},{"id":"bias","g":"ai","word":"Bias","text":"Ketika AI (atau manusia) condong secara tidak adil ke satu sisi, sering karena apa yang dipelajarinya.","also":["bias","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"AI yang bertanggung jawab","text":"Memakai AI dengan adil, aman, dan jujur, dengan manusia tetap bertanggung jawab atas hasilnya.","also":["responsible AI","ethical AI","AI etis"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Trik saat instruksi tersembunyi di halaman web atau file berusaha membuat AI melakukan sesuatu yang tidak diminta penggunanya.","also":["prompt injection","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"Batas jumlah permintaan yang boleh kamu kirim ke sebuah layanan dalam waktu tertentu. Kalau terlampaui, kamu harus menunggu.","also":["rate limit","rate limits","rate limited","batas laju"]},{"id":"usagelimit","g":"ai","word":"Batas pemakaian","text":"Seberapa banyak pekerjaan AI yang dibolehkan paketmu dalam suatu periode, setelah itu berhenti atau berbiaya lebih.","also":["usage limit","usage limits","batas pemakaian"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Membuat perangkat lunak terutama dengan menjelaskan apa yang kamu mau kepada AI dan membiarkannya menulis kodenya.","also":["vibe coding","vibe-coding"]},{"id":"budget","g":"money","word":"Anggaran","text":"Jumlah uang yang disisihkan untuk sesuatu.","also":["budget","budgets","anggaran"],"noTip":1},{"id":"costest","g":"money","word":"Perkiraan biaya","text":"Dugaan terbaik tentang berapa biaya sesuatu sebelum kamu mulai.","also":["cost estimate","cost estimates","estimasi biaya"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"Apa yang kamu dapat kembali dibandingkan dengan apa yang kamu tanam. Kalau positif, berarti sepadan.","also":["ROI","laba atas investasi"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Semua yang sebenarnya dikeluarkan untuk sesuatu selama masa pakainya, bukan hanya harga belinya: menjalankan, dukungan, peningkatan, dan akhirnya menghentikannya.","also":["TCO","total biaya kepemilikan"]},{"id":"capex","g":"money","word":"CapEx dan OpEx","text":"CapEx adalah uang yang dibelanjakan di muka untuk barang yang kamu simpan; OpEx adalah pengeluaran berkelanjutan, seperti tagihan bulanan.","also":["CapEx","OpEx","capital expenditure","operating expenditure","belanja modal","belanja operasional"]},{"id":"subscription","g":"money","word":"Langganan","text":"Membayar secara berkala, biasanya bulanan atau tahunan, agar terus bisa memakai sesuatu.","also":["subscription","subscriptions","langganan"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Perangkat lunak yang kamu pakai secara online dan bayar lewat langganan, sementara pembuatnya yang menjalankannya untukmu.","also":["SaaS"]},{"id":"payg","g":"money","word":"Bayar sesuai pemakaian","text":"Membayar hanya untuk yang kamu pakai, seperti komputasi cloud atau token AI.","also":["pay as you go","pay-as-you-go","usage-based pricing","bayar sesuai pemakaian"]},{"id":"overage","g":"money","word":"Kelebihan pemakaian","text":"Pemakaian di atas yang termasuk dalam paketmu, yang bisa dikenai biaya tambahan.","also":["overage","overages","overage charges","biaya kelebihan"]},{"id":"billingalert","g":"money","word":"Peringatan tagihan","text":"Pesan saat pengeluaran atau pemakaian mencapai tingkat yang kamu pilih. Ia memperingatkanmu, tetapi tidak selalu menghentikan biaya berikutnya.","also":["billing alert","billing alerts","spending alert","peringatan tagihan"]},{"id":"freetier","g":"money","word":"Paket gratis","text":"Tingkat gratis dari layanan berbayar, dengan batasan. Berguna untuk memulai.","also":["free tier","free plan","paket gratis"]},{"id":"pricing","g":"money","word":"Paket harga","text":"Berbagai paket yang dijual sebuah layanan, masing-masing dengan harga dan batasannya sendiri.","also":["pricing plan","pricing plans","price plan","paket harga"]},{"id":"licence","g":"money","word":"Lisensi","text":"Aturan tentang bagaimana kamu boleh memakai, menyalin, mengubah, atau membagikan sesuatu buatan orang lain, seperti perangkat lunak, huruf, atau gambar.","also":["licence","licences","license","licenses","lisensi"],"noTip":1},{"id":"opensource","g":"money","word":"Open source (sumber terbuka)","text":"Perangkat lunak yang kodenya bisa dibaca, dipakai, dan sering diubah siapa saja secara gratis, sesuai aturan lisensinya.","also":["open-source","open source","open source software","OSS","sumber terbuka"]},{"id":"osslicence","g":"money","word":"Lisensi open source","text":"Aturan yang menyertai kode open source. Ada yang membolehkan hampir apa saja (seperti MIT); ada yang meminta kamu membagikan perubahanmu juga (seperti GPL).","also":["open source licences","MIT licence","GPL","lisensi open source"]},{"id":"proprietary","g":"money","word":"Proprietari","text":"Dimiliki sebuah perusahaan dan tidak bebas disalin atau diubah. Kebalikan dari open source.","also":["proprietary","proprietary software","proprietari"]},{"id":"copyright","g":"money","word":"Hak cipta","text":"Hak hukum pencipta untuk mengendalikan salinan karyanya, termasuk kode dan tulisan.","also":["copyright","copyrighted","hak cipta"],"noTip":1},{"id":"ip","g":"money","word":"Kekayaan intelektual (IP)","text":"Gagasan dan ciptaan yang oleh hukum dianggap dimiliki, seperti kode, desain, nama, dan logo.","also":["IP","intellectual property","kekayaan intelektual"]},{"id":"tos","g":"money","word":"Ketentuan layanan","text":"Aturan yang kamu setujui saat memakai sebuah layanan.","also":["terms of service","terms and conditions","terms of use","syarat dan ketentuan","ketentuan layanan"]},{"id":"contract","g":"money","word":"Kontrak","text":"Perjanjian tertulis antara dua pihak yang dikuatkan hukum.","also":["contract","contracts","kontrak"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"Dokumen yang menguraikan persis pekerjaan apa yang akan dilakukan, kapan, dan berapa harganya.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Harga tetap","text":"Harga yang disepakati untuk seluruh pekerjaan, berapa pun lamanya.","also":["fixed price","fixed-price","harga tetap"]},{"id":"tm","g":"money","word":"Time and materials","text":"Membayar jam yang benar-benar dikerjakan dan bahan yang benar-benar dipakai, bukan harga tetap.","also":["T&M"]},{"id":"invoice","g":"money","word":"Faktur","text":"Tagihan yang meminta pembayaran atas pekerjaan yang dilakukan atau barang yang dipasok.","also":["invoice","invoices","faktur"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"Ketika berpindah dari pemasok begitu sulit atau mahal sehingga kamu terjebak bersamanya.","also":["lock-in","vendor lock-in","ketergantungan vendor"]},{"id":"procurement","g":"money","word":"Pengadaan","text":"Proses memilih dan membeli dari pemasok.","also":["procurement","pengadaan"]},{"id":"servicecredit","g":"money","word":"Service credit","text":"Uang kembali atau diskon yang kamu dapat saat pemasok melanggar SLA-nya.","also":["service credit","service credits","kredit layanan"]}]}};
